(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sc"] = {"ui":{"skip":"Brinca a su cuntenutu","back":"← Torra a AI-gile","lang.button":"Limba: {name}","lang.dialog":"Sèbera una limba","lang.search":"Chirca limbas","lang.none":"Peruna limba currispondet","lang.notYet":"{name} no est ancora tradùida","theme.aria":"Càmbia tema: craru, iscuru o nieddu","theme.toLight":"Passa a su tema craru","theme.toDark":"Passa a su tema iscuru","theme.toBlack":"Passa a su tema nieddu (nieddu beru, lèbiu pro sas pantallas OLED)","words.underline":"Sutalìnia custas paràulas in sa pàgina","words.underlineHelp":"Passa cun su cursore subra de una paràula puntigiada o tòcala pro bìdere ite cheret nàrrere.","words.col.todo":"Cartas isseberadas pro como: s'iscuadra at a cumintzare dae custas.","words.col.doing":"Un'IA est traballende in custa carta como.","words.col.review":"Un'IA at finidu su traballu; un'àtera lu controllat prima chi arribet a tie.","words.col.verify":"Ti isetat: proa e nara si funtzionat.","words.col.team":"Sas notas o sas rispostas tuas, chi isetant chi s'iscuadra las leet.","words.col.done":"Fatu e atzetadu.","index.title":"AI-gile: s'iscuadra tua de isvilupu IA, in una tàula sola","index.description":"AI-gile est una tàula kanban pro iscuadras de programmatzione cun IA. Issas traballant mentras tue dormis; a tie ti abarrat una pila curtza de cosas de detzidere, de proare e de atzetare.","hero.logoAlt":"Icona de sa tàula AI-gile","hero.h1.html":"S'iscuadra tua de isvilupu IA, in una&nbsp;tàula.","hero.alpha":"🐣 Pre-alfa serrada","hero.alphaTitle":"Galu a su printzipiu e no finidu: gràtzias de lu proare!","hero.lede":"Issas costruint mentras tue dormis. Tue ti sullevas cun una pila curtza: carchi pregonta, carchi cosa de proare, unu diamante birde-lillas o duos. Un'incarcada, atzetas, e torras a su caffè.","dl.windows":"App pro Windows","dl.browser":"Allughe·lu in su navigadore","dl.messenger":"📱 Messenger pro su telèfonu tuo","dl.soon":"Prestu","dl.notify":"🔔 Avisa·mi cando abbèrrit","dl.notifySmall":"Alfa o beta","hero.secondary":"Agile, ma s'iscuadra no tenet bisòngiu de su caffè de su stand-up. (Ma lu faghet su matessi.)","pitch.h2":"AI-gile in cantu paràulas cheres","pitch.lede":"Sèbera una longària, dae una paràula a 144. Ogni longària est una descritzione sua, iscrita pro cussa mannària. Tira su cursore o imprea sas fritzas.","pitch.rangeLabel":"Longària in paràulas","pitch.dice":"🎲 un'àtera versione","pitch.words.one":"{n} paràula","pitch.words.other":"{n} paràulas","pitch.letters.one":"{n} lìtera","pitch.letters.other":"{n} lìteras","pitch.chars.one":"{n} caràtere","pitch.chars.other":"{n} caràteres","count.line.html.one":"{n} carta in sa tàula como etotu","count.line.html.other":"{n} cartas in sa tàula como etotu","people.humans.html.one":"👥 {n} umanu","people.humans.html.other":"👥 {n} umanos","people.agents.html.one":"🤖 {n} agente","people.agents.html.other":"🤖 {n} agentes","people.working.html.one":"⚡ {n} traballende como etotu","people.working.html.other":"⚡ {n} traballende como etotu","pre.title":"AI-gile: s'est fraighende calicuna cosa","pre.description":"Inoghe s'est fraighende calicuna cosa: una tàula ue iscuadras IA fraigant su chi pedis, e t'insegnant in s'interis. Pro como pre-alfa serrada cun amigos.","pre.h1":"Inoghe s'est fraighende calicuna cosa. 🤫","pre.line":"Una tàula ue iscuadras IA fraigant su chi pedis, e t'insegnant in s'interis. Pro como pre-alfa serrada cun amigos.","pre.btn":"🔔 Avisa·mi cando abbèrrit","pre.peek":"In palas de su vidru: sa tàula vera, in direta. Ogni cartedda est una barra colorada.","pre.peekFake":"In palas de su vidru: comente paret una tàula a su traballu.","pre.night":"🌙 Su vigilante de note cumandat · 😴 s'omine pàusat","features.aria":"Ite faghet","f.pile.h":"Una pila sola pro tie","f.pile.html":"<b>Pro tie</b> regollit totu su chi t'istat abetende, de totu sos progetos: pregontas, cosas de proare, traballos chi podet fàghere isceti una persone. Sa coda tua narat ite benit a pustis e cantu tardat.","f.sleep.h":"Iscuadras chi traballant mentras tue dormis","f.sleep.p":"Ogni progetu tenet unu cabu e un'iscuadra de agentes IA. Lassa unu cummentu in una carta, s'iscuadra si sèberat, faghet su traballu e si lu torrat cun passos chi sighit fintzas una persone istraca.","f.tester.h":"Su proadore IA controllat primu","f.tester.p":"Innantis chi bessat a tie, su proadore sighit sos passos in una copia de s'app e mustrat ite at bidu, cun una catura de ischermu. Isfògia sas chi sunt passadas e atzeta cun un'incarcada.","f.proof.h":"Provas, no promissas","f.proof.p":"Ogni cunsigna mustrat ite est mudadu: sos archìvios, sa diferèntzia, sas caturas de ischermu. Nudda de abèrrere ogni app pro ischire si est fata.","f.chat.h":"Chistiona cun sos cabos tuos","f.chat.p":"Una barra a modu de Discord: un'icona pro ogni progetu, diamantes birde-lillas pro su chi tenet bisòngiu de tie. Imbia un'idea a unu cabu; issu la faghet cartas e pranu, cun unu butone ✅ Go.","f.tidy.h":"Si mantenet in òrdine","f.tidy.p":"Sas cartas parentes si fundent in una, sos tìtulos imbroglios s'acontzant, e unu controllu de sos token mantenet su còdighe lestru. Menus cosas intre sas cales andare, menus de pensare.","f.private.h":"Tua, in su computer tuo","f.private.li1":"Sa tàula girat in su computer tuo e rispondet isceti a tie.","f.private.li2":"Sos messàgios privados intre sas persones sunt cifrados dae unu cabu a s'àteru.","f.private.li3":"Peruna crèsia, peruna ispia, perunu cookie.","f.lang.h":"In sa limba tua","f.lang.p":"Prus de 120 limbas, dae s'olandesu, su galesu e su giaponesu a su de sos piratas, de Yoda e su clingon, cun unu passàgiu lestru a s'inglesu pro sas paràulas tècnicas.","f.service.h":"Dae un'idea a unu servìtziu beru","f.service.p":"As fraigadu cun s'IA calicuna cosa chi sa gente immoe impreat? Sinna·la comente servìtziu e su tabellone t'agiudat a la gestire bene: controllos de funtzionamentu, una pàgina de istadu pùblica, incidentes cun unu resumu iscritu, mudas chi tenent bisòngiu de un'Andat, còpias de seguresa controlladas ogni die. S'Agiudu t'insegnat ogni passu mentras andas a in antis.","msgr.h2":"AI-gile Messenger: s'iscuadra tua in butzaca","msgr.p1":"Faedda cun s'iscuadra IA tua sena abèrrere sa tàula. Chatta cun sos cabos de progetu e cun sos amigos tuos, bide sos passos de test de una carta e risponde, totu dae su telèfonu tuo.","msgr.p2":"Pro l'assotziare, iscansiona unu còdighe QR in sa tàula tua. Est sa prima borta? Una chat demo simpàtica ti mustrat totu.","msgr.when":"In antis Android, a pustis una versione web pro sos telèfonos e s'iPhone.","msgr.who":"Su cabu de progetu tuo","msgr.b1":"Sa curretzione de su modu iscuru est pronta. Cheres sos passos de test?","msgr.b2":"Eja, gràtzias!","msgr.b3":"1. Aberi sa Cunfiguratzione. 2. Sèbera Iscuru. Paret giustu?","tl.aria":"Lìnia de su tempus dae sa prima faedda a sa mapa de su caminu","tl.h2":"Dae sa prima faedda a su chi benit","tl.lede":"Datas e oras beras, in su fusu oràriu tuo. Dae oe in antis b'est su pranu, chene datas promìtidas.","tl.today":"Oe","tl.planned":"pranadu","tl.doing":"in cursu","tl.cards.one":"{n} carta","tl.cards.other":"{n} cartas","join.h2":"Vene puru tue","join.lede":"AI-gile lu costruit unu barbudu istranu cun AuDHD e calicuna batalla cun sa salude mentale, e una caterva de agentes pazientes. Pro como est privadu, in una alfa serrada cun amigos. Cheres proare cando s'abbèrrit?","join.btn":"Registra s'interessu","join.small":"Ti iscrimus a posta, nudda de àteru","footer.tag":"AI-gile. Peruna ispia, perunu cookie, perunu caffè de stand-up.","footer.licence":"Lissèntzia pro impresas","footer.status":"Istadu","footer.privacy":"Su chi mantenimus","footer.thanks":"Chiamadas gràtzias a ChilledChat","form.sending":"Imbiende…","form.failed":"No at funtzionadu: torra a proare a pustis.","form.offline":"No amus lòmpidu a AI-gile: torra a proare a pustis.","form.keep":"Ddu impreamus isceti pro ti rispòndere, posca ddu cantzellamus. Peruna ispia, perunu cookie.","form.keepLink":"Su chi mantenimus","interest.title":"AI-gile: avisa·mi cando s'alfa abbèrrit","interest.description":"Lassa sa posta eletrònica tua pro ischire cando s'alfa o sa beta serrada de AI-gile abbèrrit.","interest.h1":"🔔 Avisa·mi cando abbèrrit","interest.lede":"AI-gile est in pre-alfa serrada. Lassa sa posta eletrònica tua e ti iscrimus una borta isceti, cando b'at logu pro tie.","interest.email":"Sa posta eletrònica tua","interest.which":"Ite proa?","interest.alpha":"Alfa serrada: a su printzipiu, aspra, cun medas mudàntzias","interest.beta":"Beta: prus istàbile, prus a tardu","interest.both":"Cale chi siat, sa chi benit primu","interest.submit":"Pone·mi in sa lista","interest.thanks":"Gràtzias! Ses in sa lista.","licence.title":"AI-gile: lissèntzia pro impresas","licence.description":"Impreas AI-gile in s'impresa tua? Pedi una lissèntzia pro impresas de badas.","licence.h1":"📜 Lissèntzia pro impresas","licence.lede":"Impreas AI-gile a su traballu? Nara·nos chie ses e ite faghes. Si faghet unu pagu de bene, sa lissèntzia est de badas.","licence.company":"Impresa","licence.website":"Situ web","licence.what":"Ite faghes","licence.how":"Comente agiudat su mundu","licence.email":"Posta eletrònica","licence.submit":"Imbia sa dimanda","licence.thanks":"Gràtzias! Ti rispondimus a posta.","status.title":"Istadu de AI-gile","status.h1":"Istadu de AI-gile","status.quiet":"Totu in paghe","status.intro":"AI-gile est funtzionende como? Custa pàgina controllat su situ, sa cumpartzidura de tàulas, sas mutidas e s'iscarrigamentu ogni 5 minutos.","status.up":"Funtzionat (at rispostu in {ms} ms)","status.slow":"No at rispostu a s'ùrtimu controllu, torramus a proare","status.down":"Non funtzionat: no at rispostu a sos ùrtimos duos controllos","status.svc.web":"Situ web","status.svc.web.offers":"Custu situ: ite est AI-gile, e su mòdulu de interessu","status.svc.boards":"Cumpartzidura de tàulas","status.svc.boards.offers":"Tàulas pùblicas, messàgios intre amigos e invitos","status.svc.calls":"Mutidas","status.svc.calls.offers":"Boghe, vìdeu e cumpartzidura de s'ischermu in AI-gile","status.svc.download":"Iscarrigamentu","status.svc.download.offers":"S'installadore pro Windows e sos ligòngios de invitu","status.checking":"Controllende…","status.offline":"Como no resessimus a lòmpere a su servìtziu de s'istadu (torramus a proare)","status.updated":"agiornadu {ago}","status.justNow":"como etotu","status.min":"{n} min a como","status.hours":"{n} h a como","status.days":"{n} d a como","privacy.title":"AI-gile: su chi mantenimus","privacy.h1":"Su chi mantenimus","privacy.lede":"In curtzu: isceti su chi nos mandas, e non pro meda tempus.","privacy.only":"Isceti su chi nos mandas: su chi iscries in unu mòdulu, comente sa posta eletrònica tua. Nudda de prus subra de tie.","privacy.sealed":"Est sigilladu gasi su serbidore nostru no ddu podet lèghere: in su navigadore tuo, in antis chi partat (in unu navigadore prus betzu, in su momentu chi lòmpet). Isceti sa tàula nostra ddu podet abèrrere.","privacy.server":"Est cantzelladu dae su serbidore comente lòmpet a sa tàula nostra. Totu su chi b'est galu a pustis de 30 dies est cantzelladu su matessi.","privacy.board":"Ddu mantenimus in sa tàula nostra isceti fintzas a cando ti rispondimus, posca ddu cantzellamus fintzas inie.","privacy.none":"Peruna ispia, perunu cookie, peruna anàlisi.","privacy.local":"Sa limba tua e su sèberu de tema craru o iscuru abarrant in su navigadore tuo. Non nos benint mai mandados.","privacy.ask":"Cheres chi isparessat prima? Iscrienos rispondende a sa posta nostra.","live.h2":"Càstia comente lu istant fraigende, in direta","live.caption":"Ogni cartedda est cuada: bides sa forma de su traballu, no sas paràulas.","live.watching.one":"in direta: {n} chi càstiat","live.watching.other":"in direta: {n} chi càstiant","live.last.now":"Ùrtima carta mòvida como pròpiu","live.last.min.one":"Ùrtima carta mòvida {n} minutu ha","live.last.min.other":"Ùrtima carta mòvida {n} minutos ha","live.last.hour.one":"Ùrtima carta mòvida {n} ora ha","live.last.hour.other":"Ùrtima carta mòvida {n} oras ha","live.last.day.one":"Ùrtima carta mòvida {n} die ha","live.last.day.other":"Ùrtima carta mòvida {n} dies ha","live.offline":"Sa tabella in direta si leat un'alenu. Torra a nde bìere in curtzu.","live.cols":"Backlog|De fàghere|In cursu|Controllu de s'iscuadra|Pro tie de testare|Pro s'iscuadra|Fatu"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Delegadu."]},{"n":2,"texts":["Kanban robòticu.","Agentes, organizados.","Ideas, costruidas."]},{"n":3,"texts":["Kanban pro robots.","Ideas diventant funtziones.","Kanban pro agentes IA."]},{"n":5,"texts":["Una tàula kanban guvernada dae agentes.","Tue iscries cartas. Sos agentes costruint.","De badas, locale, proadu, mattu."]},{"n":8,"texts":["Una tàula kanban de badas inue traballant agentes IA.","Iscrie un'idea. Sos agentes la costruint. Tue atzetas.","Agile pro una persone e medas robots pazientes."]},{"n":13,"texts":["Una tàula kanban in su computer tuo, inue sos agentes IA leant sas cartas.","Iscrie un'idea. Un'iscuadra de agentes la costruit. Unu proadore la controllat.","De badas, chene crèsias nen ispias: una tàula, carchi robot e tue a cumandu."]},{"n":21,"texts":["AI-gile est una tàula kanban pro traballare cun agentes IA chi programmant. Issos leant sas cartas; tue las proas e las atzetas.","Ogni progetu tenet unu cabu e un'iscuadra de agentes IA. Lassa unu cummentu in cale chi siat carta e s'iscuadra si ponet a traballare.","Una lista personale de cosas de fàghere, de badas, chi girat in su computer tuo. Sos traballadores sunt robots. Chie narat eja ses tue."]},{"n":34,"texts":["Pones ideas in una tàula. Un'iscuadra de agentes IA las faghet funtziones chi andant, las proat e si las torrat cun passos de proare. Nudda est fatu fintzas a cando tue dis chi est fatu.","AI-gile est una tàula kanban fata in domo, chi Rich at costruidu cun meda agiudu dae sos agentes chi como guvernat issa. Est de badas, girat in su computer tuo e si dat a sos amigos, no si bendet.","Pensa a una tàula kanban normale, cun colunnas dae Backlog a Fatu, ma cun sas cartas leadas dae agentes IA. Issos contant ite est faghende, pregontant cando s'imbrogliant e abetant sempre su bonu tuo."]},{"n":55,"texts":["AI-gile est una tàula kanban inue s'iscuadra est fata de agentes IA. Ogni progetu tenet unu cabu chi pranat su traballu e agiudantes chi lu costruint. Cando una funtzione est pronta, unu proadore IA la proat e faghet una catura de ischermu, e a pustis lòmpet a sa pila tua. La atzetas, o lassas unu cummentu e issos la torrant a fàghere.","Est nàschida comente manera de una persone de sighire medas sessiones de programmatzione cun IA a una borta, e est creschida in una tàula beru. Girat in su computer tuo, no tenet bisòngiu de crèsia e no tenet ispias. Est de badas pro sos amigos e pro chie est curiosu. Est ancora a mesu, duncas isetta·ti ispigos aspros e carchi surpresa.","Custa est sa versione sinchera. Sas ideas las depes ancora tènnere tue, e sos resultados los depes ancora controllare tue. Ite faghet AI-gile est totu su chi b'at in mesu: mantenet sas cartas in òrdine, sèberat s'agente giustu cando cummentas, mustrat propriu ite est mudadu e regollit totu in una pila curtza pro tie."]},{"n":89,"texts":["AI-gile est una tàula kanban de badas chi faghes girare in su computer tuo etotu. In logu de persones, ogni progetu tenet un'iscuadra de agentes IA: unu cabu chi faghet de sas ideas tuas cartas e unu pranu, e agiudantes chi leant sas cartas segundu sa prioridade. Cando carchi cosa est costruida, unu proadore IA sighit sos passos de proa e ti mustrat ite at bidu. A pustis abetat in una pila sola chi si narat Pro tie. La atzetas, o lassas unu cummentu e s'iscuadra torrat a proare. Nudda lòmpet mai a Fatu chene tie.","Carchi cosa chi forsis no ti isetas. Una guardia de note mantenet piena sa colunna De fàghere mentras tue dormis, sèberende cartas chi no cheren peruna risposta dae tie. Unu contadore de token mustrat cantu sos agentes ant impreadu oe e custa chida, e su Modu chene token lis narat de non ispèndere. Ti podes iscriere cun sos amigos, e sos messàgios privados sunt cifrados dae unu cabu a s'àteru. Sa tàula faeddat de a pagu 120 limbas, comprendende s'olandesu, su fiammingu, sos piratas e su clingon. Nudda de custu costat unu soddu, e perunu est chirchende de te lu bèndere.","AI-gile est unu progetu minore e personale, no una sotziedade. Rich cheriat tènnere a ojos medas progetos de programmatzione cun IA chene abèrrere ogni app a los controllare, duncas issu e sos agentes ant fatu una tàula pro custu, e a pustis ant impreadu sa tàula pro costruire su restu. Est in pre-alfa serrada, chi cheret nàrrere chi funtzionat, in prevalèntzia, pro unu pugnu de amigos. Non b'at pàgina de prètzios, newsletter nen pranu de crèschida. Si ti paret ùtile, podes pedire de lu proare cando s'abbèrrit unu pagu de prus."]},{"n":144,"texts":["AI-gile est una tàula kanban pro una persone e una caterva de agentes IA. Girat in su computer tuo e est de badas dae sa conca a sos pes. Agiunghes progetos, e ogni progetu tenet unu cabu e un'iscuadra pitica. Chistionas cun su cabu, unu pagu comente in Discord, e li contas un'idea; issu la faghet cartas e pranu, e a pustis abetat chi tue incarches Go. S'iscuadra faghet sas cartas segundu sa prioridade, cun una lìnia de cumandu simple fata pro sos modellos de limba. Innantis chi carchi cosa torret a tie, unu proadore IA sighit sos passos in una copia de s'app e allegat una catura de ischermu. Su traballu finidu lòmpet a sa pila tua cun sos archìvios mudados e sa diferèntzia. Lu atzetas, o lassas unu cummentu e s'iscuadra si sèberat e torrat a proare. Isceti tue podes mòvere una carta a Fatu.","Una die cun AI-gile, in sustàntzia. A sero lassas carchi cummentu: custu butone est in su logu isballiadu, cussa lista depet èssere ordinada, podimus tènnere unu tema iscuru. Ti ch'andas a durmire. Sos agentes leggint sos cummentos, faghent sas mudàntzias, las proant e ti las torrant. Si De fàghere si mutit, sa guardia de note lu piticat dae su backlog cun cartas chi no cheren peruna risposta dae tie. Sa manzanu b'at una pila curtza sola: duas pregontas e carchi cosa de proare, cada una cun passos chi sighit fintzas una persone dormida e una catura de ischermu chi mustrat chi funtzionat. Passas, atzetas sas bonas e torras su restu. Unu contadore de token mustrat ite b'est andadu, e su Modu chene token est pro sas chidas magras. Pustis faghes colatzione, e in custu sos agentes no podent ancora agiudare.","In primu, ite no est AI-gile. No est una startup, no est in vendita e nemos regollit sos datos tuos. Est una tàula de badas chi girat in su computer tuo, chene crèsias, ispias nen cookie. Ite est: unu logu sulidu inue bìdere totu sos progetos de programmatzione cun IA in una borta, cun un'iscuadra de agentes chi faghet sas cartas e tue chi detzides. Fundet sas cartas parentes, acontzat sos tìtulos imbroglios e istat in atentu a comente abarrat lestru su còdighe. Faeddat de a pagu 120 limbas, dae s'olandesu e su fiammingu a sos piratas e su clingon. Sos amigos si podent iscriere intre issos, in privadu e cifradu. L'ant costruida Rich e una caterva de agentes pazientes, mescamente impreende·la issa matessi. Est in pre-alfa serrada, duncas in logos est aspra. Si ti paret divertente, pedi cun bona manera e forsis intras in antis."]}],"quips":{"1":"Una paràula. Curaggiosa. Forsis tropu curaggiosa.","3":"Tres paràulas. Giai prus sinceras de sa majoria de sas pàginas de produtu.","8":"Oto paràulas. Ancora prus curtzas de unu stand-up.","21":"Sas longarias sunt story points, a proposìtu. Ma certu.","55":"Cincuantacincu paràulas. Duas cartas si sunt finidas mentras lèghias.","144":"Custa est sa longa. Non b'at 233. Sos agentes ch'ant a durmire."}},"timeline":{"first-idea.name":"Sa prima idea","first-idea.line":"Sa prima faedda, innantis chi esistereret perunu còdighe.","first-board.name":"Sa prima tàula","first-board.line":"Una tàula chi sighit sa costrutzione sua matessi: cartas, colunnas, trìbulu e lassa, progetos.","team-roles.name":"Iscuadra e roles","team-roles.line":"Profilos de agentes, modellos de iscuadra, ispàtzios e chie faghet ite.","install.name":"Installatzione e versiones","install.line":"Unu zip chi unu amigu podet installare, agiornamentos a solu, canales e torrada a segus.","usage-saver.name":"Impreu a lestru","usage-saver.line":"Mesurare ite costant sas aviadas, mantènnere su còdighe lestru, sarvare su lìmite.","friends.name":"Amigos e cumpartzidura","friends.line":"MP privados, unu relay cifradu, invitos, roles e progetos cumpartzidos.","languages.name":"Limbas","languages.line":"Ònnia testu de ischermu in unu documentu de limba, cun s'olandesu e su fiammingu primos.","ai-tester.name":"Proadore IA","ai-tester.line":"Unu proadore controllat ònnia cunsigna primu e mustrat ite at bidu.","website.name":"Su situ web","website.line":"aigile.lol, su teaser e custa lìnia de su tempus.","streaming.name":"Chat e streaming","streaming.line":"Discord, Twitch, OBS, modu streamer, GIF e emoji.","no-ai.name":"Edissione chene IA","no-ai.line":"Una tàula pro chie programmat chene IA, e tàulas pùblicas.","night-watch.name":"Guardia de note","night-watch.line":"Unu guardianu e unu Scrum Master mantenent sas iscuadras a traballu mentras tue dormis.","p-more.name":"Totu su restu","p-more.line":"Ideas prus piticas chi abetant su turnu issoro.","p-android.name":"Telèfonu e Android","p-android.line":"Lòmpere a sa tàula dae su telèfonu, e a pustis cun un'app Android nativa.","p-release.name":"Alfa e a pustis","p-release.line":"Alfa serrada, su situ in direta, a pustis sa beta.","p-languages.name":"Prus limbas","p-languages.line":"130 limbas, e una modalidade de immersione pro chie est imparende.","p-engines.name":"Prus motores IA","p-engines.line":"Sèbera Claude, Codex, Gemini, Copilot o Cursor pro ogni agente.","p-pro.name":"Pratica professionale","p-pro.line":"Etichetas de risicu, barrieras de unione, cartas de incidente e protetziones.","p-self.name":"Cura de tie","p-self.line":"Modu istracu, remindatziones de cura de tie e 4:20.","p-servers.name":"Servidores e iscala","p-servers.line":"Impostatziones globales de servidore, roles e pranos pro creschere.","p-livestream.name":"Agiuntas de streaming","p-livestream.line":"Chat de Twitch, emoji personalizados e una vista pùblica in direta."},"words":{"button":"📖 Paràulas tècnicas","h":"📖 Paràulas ispiegadas","intro":"Formatzione de badas in limba crara: ònnia paràula chi agatas dae una prima idea finas a unu servìtziu chi sa gente bi contat, cun s'Agile, su costruire, su mantènnere seguru e su traballare cun s'IA in caminu.","search":"Chirca una paràula…","none":"Peruna paràula currispondet.","close":"Serra","count":{"one":"{count} paràula","other":"{count} paràulas"},"groups":[{"id":"idea","name":"💡 Idea e iscoberta"},{"id":"plan","name":"🗺️ Pianificare su traballu"},{"id":"agile","name":"🔁 Maneras agile de traballare"},{"id":"build","name":"🛠️ Fràigare"},{"id":"test","name":"🧪 Proas e calidade"},{"id":"change","name":"🔀 Mudare cun seguresa"},{"id":"run","name":"🛎️ Gestire unu servìtziu"},{"id":"sec","name":"🔒 Seguresa e riservadesa"},{"id":"ai","name":"🤖 Traballare cun sa IA"},{"id":"money","name":"💰 Dinare e lissèntzias"}],"list":[{"id":"discovery","g":"idea","word":"Iscoberta","text":"Sa fase de cumintzu, cando s'iscoberit cale problema bàlet sa pena de resòlvere e pro chie, in antis de costruire calicuna cosa.","also":["fase de iscoberta"]},{"id":"problemstmt","g":"idea","word":"Declaratzione de su problema","text":"Una o duas fràsias chi nant chie tenet unu problema, ite est e proite importat, gasi totus mirant a sa matessi cosa.","also":["declaratziones de su problema"]},{"id":"user","g":"idea","word":"Utente","text":"Una persone chi impreat su chi costruis. Sos bisòngios suos sunt sa resone de su traballu.","also":["utentes"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Parte interessada","text":"Cale si siat persone chi tenet a coro comente andat su traballu o chi nd'est tocada, comente chie pagat, chie l'impreat o chie lu sustenet.","also":["partes interessadas"]},{"id":"persona","g":"idea","word":"Persona","text":"Una persone imaginada ma realista chi rapresentat una zenia de utente, gasi s'iscuadra si podet pregontare «Sam l'at a agatare fàtzile?»","also":["personas"]},{"id":"userresearch","g":"idea","word":"Chirca cun sos utentes","text":"Faeddare cun persones beras e las osservare pro cumprèndere de ite tenent bisòngiu, imbetzes de andare a tentu.","also":["user interviews","intervistas a sos utentes"]},{"id":"journey","g":"idea","word":"Percursu de s'utente","text":"Sos passos chi una persone faghet pro cumpletare calicuna cosa, dae cando nde intendet faeddare finas a s'acabu, fintzas foras de su produtu tuo. Si los disinnas, bides inue s'incastat.","also":["percursos de s'utente","percursu de su cliente"]},{"id":"painpoint","g":"idea","word":"Puntu dolorosu","text":"Calicuna cosa chi infadat o rendet lentas sas persones oe. Sos produtos bonos bogant sos puntos dolorosos.","also":["puntos dolorosos"]},{"id":"assumption","g":"idea","word":"Supositzione","text":"Calicuna cosa chi crees ma non as ancora controlladu. Iscriende sas supositziones bides ite proare in antis.","also":["supositziones"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Ipòtesi","text":"Una previsione chi pensas de controllare, cun su chi t'isetas chi at a capitare, comente «sa gente s'at a registrare si su primu mese est de badas».","also":["ipòtesis"]},{"id":"experiment","g":"idea","word":"Esperimentu","text":"Una proa pitica e pianificada pro cumprèndere si un'idea funtzionat, in antis de bi puntare meda.","also":["esperimentos"],"noTip":1},{"id":"poc","g":"idea","word":"Proa de cuntzetu (PoC)","text":"Una proa lestra e a s'ingrussu pro bìdere si un'idea podet funtzionare a beru. A su sòlitu si ghetat cando tenes sa risposta.","also":["PoC","proa de cuntzetu","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototipu","text":"Unu modellu de cumintzu de su produtu, a s'ispissu immàgines chi si podent incarcare, pro proare s'idea cun sa gente in antis de lu costruire comente si depet.","also":["prototipos"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Unu disinnu simpre de un'ischermada chi mustrat inue andant sas cosas, sena colores nen cuntenutu beru.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Una immàgine detallada de comente at a pàrrere un'ischermada, cun colores e testu beros, ma nudda funtzionat ancora.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"Sas resones pro fàghere unu progetu: ite costat, ite portat o ite sarvat, e sos arriscos.","also":["business cases","casu de afares"]},{"id":"feasibility","g":"idea","word":"Fatibilidade","text":"Si calicuna cosa si podet beru costruire e mantènnere cun su tempus, su dinare e sas cumpetèntzias chi tenes.","also":["fatìbile"]},{"id":"outcome","g":"idea","word":"Resultadu","text":"Su càmbiu chi boles pro sas persones, comente prus pagos apuntamentos mancados. Importat de prus de cantu costruis.","also":["resultados"],"noTip":1},{"id":"output","g":"idea","word":"Produtzione","text":"Calicuna cosa chi s'iscuadra faghet, comente un'ischermada noa o unu raportu. Chi siat fata no cheret nàrrere chi agiudet a calicunu.","also":["produtziones"],"noTip":1},{"id":"successmetric","g":"idea","word":"Mesura de sutzessu","text":"Unu nùmeru chi ti narat si su traballu at fatu su chi depiat, comente prus persones chi acabant s'ordinatzione.","also":["mesuras de sutzessu"]},{"id":"kpi","g":"idea","word":"Indicadore crae de rendimentu (KPI)","text":"Unu nùmeru importante chi sighis pro bìdere si sas cosas andant bene, comente sas registratziones a chida.","also":["KPI","KPIs","indicadore crae de rendimentu"]},{"id":"okr","g":"idea","word":"Obietivos e resultados craes (OKR)","text":"Una manera de pònnere sas metas: s'obietivu narat ite boles, e pagos resultados craes sunt sos nùmeros chi mustrant chi l'as lòmpidu.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Produtu","text":"Sa cosa chi si costruit e si curat pro sos utentes suos, comente un'app, unu situ web o un'aina.","also":["produtos"],"noTip":1},{"id":"vision","g":"plan","word":"Visione de su produtu","text":"Una declaratzione curtza de chie agiudat su produtu e de inue est andende a longu tèrmine.","also":["declaratzione de visione"]},{"id":"po","g":"plan","word":"Mere de su produtu (PO)","text":"Sa persone chi detzidet ite si costruit e in ite òrdine, gasi s'iscuadra traballat semper in su chi importat de prus. In AI-gile ses tue.","also":["PO","meres de su produtu"]},{"id":"pm","g":"plan","word":"Responsàbile de su produtu (PM)","text":"Sa persone chi tenet cura de sa diretzione de unu produtu: ite problemas resolvet, pro chie e proite. PM podet nàrrere fintzas responsàbile de progetu, duncas controlla cale.","also":["responsàbiles de su produtu"]},{"id":"projmgr","g":"plan","word":"Responsàbile de progetu","text":"Sa persone chi mantenet unu progetu in tempus e in budget, sighinde chie faghet ite e pro cando.","also":["responsàbiles de progetu"]},{"id":"roadmap","g":"plan","word":"Mapa de camminu","text":"Unu pianu a s'ingrussu de su chi benit in sos meses chi sighint, in òrdine. Mustrat sa diretzione, no datas esatas, e càmbiat a pagu a pagu chi impares.","also":["mapas de camminu"]},{"id":"milestone","g":"plan","word":"Passu de importu","text":"Unu puntu de unu progetu chi bàlet sa pena de sinnalare, comente «prima versione in lìnea» o «100 utentes».","also":["passos de importu"]},{"id":"mvp","g":"plan","word":"Produtu mìnimu bàlidu (MVP)","text":"Sa versione prus pitica de unu produtu chi est ancora de utilidade pro persones beras, gasi podes imparare dae issas dae su cumintzu.","also":["MVP","MVPs","minimum viable product","produtu mìnimu bàlidu"]},{"id":"requirement","g":"plan","word":"Requisitu","text":"Calicuna cosa chi su produtu acabadu depet fàghere o èssere.","also":["requisitos"],"noTip":1},{"id":"scope","g":"plan","word":"Àmbitu","text":"Ite est cumpresu in su traballu e, cosa importante a su matessi, ite no.","also":["in s'àmbitu","foras de s'àmbitu"]},{"id":"scopecreep","g":"plan","word":"Crèschida de s'àmbitu","text":"Cando si agiunghent cosas a su traballu a pagu a pagu, sena chi nemos s'acordet subra de su tempus o de su costu in prus, e gasi no acabat mai de su totu.","also":["crèschida de funtzionalidades"]},{"id":"feature","g":"plan","word":"Funtzionalidade","text":"Una cosa chi su produtu podet fàghere pro sas persones, comente «torra a impostare sa crae».","also":["funtzionalidades"],"noTip":1},{"id":"epic","g":"plan","word":"Èpica","text":"Unu traballu mannu, tropu pro lu fàghere in una borta, e duncas partzidu in cartas prus piticas.","also":["èpicas","epic","epics"]},{"id":"story","g":"plan","word":"Istòria de s'utente","text":"Unu traballu piticu iscritu dae sa parte de s'utente: «Comente cumpradore, cheria pòdere sarvare su carrellu meu pro l'acabare a pustis.» Aberit una cunversatzione subra de ite costruire.","also":["istòrias de s'utente"]},{"id":"ac","g":"plan","word":"Critèrios de atzetatzione (AC)","text":"Sas verìficas chi una carta depet passare pro èssere cunsiderada fata, cuncordadas in antis chi su traballu cumintzet, comente «su carrellu b'est ancora a pustis de essire e torrare a intrare».","also":["critèrios de atzetatzione"]},{"id":"task","g":"plan","word":"Cumpitu","text":"Unu traballu sìngulu de fàghere, a s'ispissu unu passu piticu de un'istòria prus manna.","also":["cumpitos"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Un'àtera paràula pro «carta»: unu traballu o una dimanda, sighidu dae su cumintzu a s'acabu.","also":["tickets"]},{"id":"priority","g":"plan","word":"Prioridade","text":"Cantu est importante o urgente calicuna cosa cumparada cun totu su restu, gasi su traballu prus importante andat in antis.","also":["prioridades"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritizatzione","text":"Pònnere su traballu in òrdine de importu. Una manera comuna est MoSCoW: Depet bi èssere, Diat dèpere bi èssere, Podet bi èssere, Custa borta no.","also":["prioritizende","prioritizare","MoSCoW"]},{"id":"estimate","g":"plan","word":"Istima","text":"Unu càlculu a ogru de cantu est mannu o de cantu durat unu traballu. Est un'istima, no una promissa.","also":["istimas","istimatzione"],"noTip":1},{"id":"storypoints","g":"plan","word":"Puntos de istòria","text":"Una manera de istimare sa mannària de su traballu cumparende cartas una cun s'àtera («prus o mancu duas bortas custa»), imbetzes de oras. No sunt pro cumparare iscuadras.","also":["puntu de istòria"]},{"id":"tshirt","g":"plan","word":"Mesuras de T-shirt","text":"Istimare sa mannària de su traballu comente S, M, L o XL. Lestru e bastante bonu pro sa pianificatzione de cumintzu.","also":["t-shirt sizing","t-shirt sizes","mesuras de t-shirt"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Unu giogu pro istimare: totus mustrant una carta de mannària a su matessi tempus, e tando chie at postu su valore prus artu e prus bàsciu narat proite.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dipendèntzia","text":"Cando unu traballu non podet cumintzare o acabare finas a cando non cumintzat o acabat un'àteru.","also":["dipendèntzias"]},{"id":"blocker","g":"plan","word":"Impedimentu","text":"Cale si siat cosa chi in custu momentu no lassat andare su traballu in antis, comente una risposta chi mancat o un'aina segada.","also":["impedimentos"]},{"id":"deadline","g":"plan","word":"Data lìmite","text":"Sa data intro de sa cale calicuna cosa depet èssere acabada.","also":["datas lìmite"],"noTip":1},{"id":"deliverable","g":"plan","word":"Cosa de consignare","text":"Calicuna cosa cuncreta chi su traballu produit e consignat, comente una pàgina chi funtzionat o unu raportu.","also":["cosas de consignare"]},{"id":"forecast","g":"plan","word":"Previsione","text":"Una previsione de su chi at a capitare probabilmente, comente cando at a èssere acabadu su traballu, a pàrtire dae su chi ischis finas a como.","also":["previsiones"],"noTip":1},{"id":"metric","g":"plan","word":"Mètrica","text":"Cale si siat cosa chi mesuras e sighis in su tempus, comente sas visitas a una pàgina o cantu tempus bi cheret pro acontzare unu problema.","also":["mètricas"]},{"id":"feedback","g":"plan","word":"Feedback","text":"Su chi sa gente ti narat de su traballu tuo, in bonu e in malu. Lu retzire chitzo e a s'ispissu est su coro de s'Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Sa lista de isetu de ideas e de traballu non ancora pianificadu, cun su prus importante in artu. Nudda de cussu benit traballadu finas a cando no passat a De fàghere."},{"id":"sprint","g":"agile","word":"Sprint","text":"Unu perìodu curtzu e fissu de traballu (a s'ispissu una o duas chidas, mai prus de unu mese) cun una meta e un'incùngiu cunvènidu de cartas de acabare.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Unu puntu lestru de cada die: ite at fatu cada persone de s'iscuadra, ite at a fàghere como, e ite la blocat. In Scrum si narat daily scrum.","also":["standup","stand-ups","daily scrum","daily stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Una manera de traballare inue sas cartas si movent pro sas colonnas de una tàula (comente De fàghere, In cursu, Fatu) e s'iscuadra limitat cantu b'at in cursu a sa borta, gasi su traballu sighit a andare."},{"id":"wip","g":"agile","word":"Lìmite WIP","text":"WIP cheret nàrrere «work in progress», traballu in cursu. Unu lìmite WIP est su nùmeru màssimu de cartas chi una colonna diat dèpere tènnere a sa borta, gasi s'iscuadra acabat sas cosas in antis de nde cumintzare àteras.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definitzione de Fatu","text":"Sa lista curtza de s'iscuadra de su chi cheret nàrrere “acabadu”, comente proadu e ispiegadu, in antis chi una carta lompat a tie. Sa gemella sua, sa Definitzione de Prontu, narat cando una carta est crara bastante pro incumintzare.","also":["Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retro","text":"Una mirada regulare in segus a comente traballat s'iscuadra, pro s'acordare subra de una o duas cosas de fàghere mègius sa borta chi benit. Abbreviatzione de «retrospective». In AI-gile una retro proponet unu càmbiu a sa manera de traballare de s'iscuadra, e tue naras Go o Non ancora.","also":["retrospetiva","retrospetivas"]},{"id":"swarm","g":"agile","word":"Isciamu","text":"Totus impare: medas persones lassant s'àteru traballu pro acontzare impare una cosa urgente finas a cando est resolta. In AI-gile cada iscuadra agiudat in unu progetu, e sos àteros progetos isetant in s'interis.","also":["isciamare","swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"In Scrum, sa persone chi agiudat s'iscuadra a traballare bene: lìberat su chi la firmat, mantenet sas riuniones in caminu e allenat bonas abitudines, sena cumandare a nemos. In AI-gile su Lead Scrum Master bidet sas cartas firmas, ispinghet sas iscuadras e ti regordat su chi est isetende, in cada progetu.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Una manera de traballare a passos pitichinnos: costruire pagu, mustrare resultados beros a s'ispissu, imparare dae su chi narat sa zente e cambiare su pianu in caminu, imbetzes de pianificare totu in antis.","also":["Isvilupu agile","maneras agile de traballare"]},{"id":"manifesto","g":"agile","word":"Manifestu Agile","text":"Una declaratzione curtza iscrita in su 2001 dae chie faghiat software. Ponet sas persones, sos resultados chi funtzionant, su traballu acurtzu a sos clientes e sa risposta a sos càmbios in antis de sos pianos pesantes e de sa burocratzia.","also":["Manifestu pro s'isvilupu agile de su software"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"Sa manera antiga de traballare: pianificare totu, a pustis costruire totu, a pustis proare totu, una fase a pustis de s'àtera. Sos càmbios fatos a tardu sunt difìtziles e caros.","also":["modellu waterfall"]},{"id":"iteration","g":"agile","word":"Iteratzione","text":"Unu giru de costruire calicuna cosa, de la controllare e de la megiorare. Su traballu agile est una cadena de custos giros, e unu sprint nde est una zenia.","also":["iteratziones"]},{"id":"increment","g":"agile","word":"Incrementu","text":"Una parte noa chi funtzionat, agiunta a su produtu in unu sprint o in unu giru de traballu, chi andat bene cun su chi b'aiat giai.","also":["incrementos"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Una manera agile de traballare meda connota: un'iscuadra pitica traballat in sprint curtzos cara a una meta, cun rolos fissos e pagas riuniones regulares pro pianificare, controllare e megiorare."},{"id":"scrumteam","g":"agile","word":"Iscuadra Scrum","text":"Su grupu piticu chi faghet su traballu in Scrum: unu mere de su produtu, unu Scrum Master e sos isvilupadores.","also":["iscuadras Scrum"]},{"id":"ceremonies","g":"agile","word":"Eventos Scrum","text":"Sas riuniones regulares de Scrum: sa pianificatzione de su sprint, su daily scrum, sa revisione de su sprint e sa retro. Medas persones las giamant tzerimònias.","also":["tzerimònias","tzerimònias Scrum"]},{"id":"sprintplan","g":"agile","word":"Pianificatzione de su sprint","text":"Sa riunione a su cumintzu de unu sprint inue s'iscuadra acordat proite su sprint importat, ite cartas pigare e comente incumintzare.","also":["riunione de pianificatzione"]},{"id":"sprintgoal","g":"agile","word":"Meta de su sprint","text":"Una fràsia chi narat a ite serbit unu sprint. Sos cumpitos piticos podent cambiare in caminu, basta chi sa meta siat lòmpida.","also":["metas de su sprint"]},{"id":"sprintbacklog","g":"agile","word":"Backlog de su sprint","text":"Sas cartas sèberadas pro su sprint de como, cun su pianu de s'iscuadra pro las fàghere.","also":["backlogs de su sprint"]},{"id":"productbacklog","g":"agile","word":"Backlog de su produtu","text":"Sa lista cumpleta e ordinada de totu su chi si podet costruire pro su produtu, su prus importante in artu. Sighit a cambiare mentras impares.","also":["backlogs de su produtu"]},{"id":"productgoal","g":"agile","word":"Meta de su produtu","text":"Su resultadu prus mannu a su cale su produtu est traballende, chi agiudat s'iscuadra a sèberare ite fàghere a pustis.","also":["metas de su produtu"]},{"id":"refinement","g":"agile","word":"Afinamentu de su backlog","text":"Rebìdere su backlog cada tantu pro assentare, partzire, pònnere in òrdine e agiùnghere detàllios a sas cartas, gasi sunt prontas de pigare. Si narat fintzas pulimentu de su backlog (backlog grooming).","also":["pulimentu de su backlog","afinamentu"]},{"id":"sprintreview","g":"agile","word":"Revisione de su sprint","text":"Una riunione a s'acabu de unu sprint inue s'iscuadra mustrat su chi at finidu e intendet ite pensat sa zente, pro detzidere ite benit a pustis.","also":["revisiones de su sprint"]},{"id":"demo","g":"agile","word":"Demo","text":"Mustrare su traballu acabadu chi funtzionat, in direta, a sas persones chi l'ant dimandadu.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"Una cantidade fissa de tempus pro calicuna cosa. Cando finit, ti firmas, fintzas si no est totu acabadu.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velotzidade","text":"Cantu traballu un'iscuadra acabat de sòlitu in unu sprint, impreadu pro pianificare cantu nde pigare sa borta chi benit. No est unu puntègiu de cantu traballant forte sas persones.","also":["velotzidade de s'iscuadra"]},{"id":"capacity","g":"agile","word":"Capatzidade","text":"Cantu traballu s'iscuadra podet pigare in unu perìodu, a pustis de vacàntzias e àteros cumpitos.","noTip":1},{"id":"burndown","g":"agile","word":"Gràficu burndown","text":"Unu gràficu de su traballu chi abarrat in unu sprint, chi falat die pro die. Si sa lìnea non falat, calicuna cosa est blocada.","also":["burndown","gràficu burn-down"]},{"id":"burnup","g":"agile","word":"Gràficu burnup","text":"Unu gràficu de su traballu acabadu chi artziat cun su tempus, a costadu de su totale pianificadu, gasi bides cando b'as a lòmpere.","also":["burnup","gràficu burn-up"]},{"id":"kanbanboard","g":"agile","word":"Tàula Kanban","text":"Sa tàula etotu: una colonna pro cada fase de su traballu, cun sas cartas chi passant dae una a s'àtera.","also":["Kanban boards","tàulas Kanban"]},{"id":"pullsys","g":"agile","word":"Sistema a tirada","text":"Una manera de traballare inue su traballu nou cumintzat isceti cando calicunu tenet logu pro lu pigare, imbetzes de bènnere postu subra de unu pratu giai prenu.","also":["a tirada"]},{"id":"flow","g":"agile","word":"Fluxu","text":"Cantu andat lisu su traballu in sa tàula. Unu fluxu bonu cheret nàrrere chi sas cartas sighint a si mòvere imbetzes de s'acumulare.","also":["fluxu de su traballu"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"Cantu tempus passat dae cando calicunu dimandat una cosa a cando est acabada.","also":["lead times","tempus de cunsigna"]},{"id":"cycletime","g":"agile","word":"Tempus de ciclu","text":"Cantu tempus pigat una carta dae cando su traballu cumintzat beru a cando est acabada.","also":["tempos de ciclu"]},{"id":"throughput","g":"agile","word":"Produtividade","text":"Cantas cartas si acabant in una chida, o in cale si siat tempus fissu.","also":["ritmu de produtzione"]},{"id":"bottleneck","g":"agile","word":"Tzugu de ampulla","text":"S'ùnica fase inue su traballu s'acumulat e faghet andare a bellu totu su chi benit a pustis, comente su tzugu istrintu de un'ampulla.","also":["bottleneck","bottlenecks","tzugos de ampulla"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"Una fila chi rughet sa tàula e aunit cartas de una zenia, comente su traballu urgente o sas cartas de un'iscuadra.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Una manera de traballare chi bogat s'ispreu (totu su chi no agiudat su cliente) e mantenet su traballu in movimentu."},{"id":"waste","g":"agile","word":"Ispreu","text":"In Lean, totu su chi costat fatigu ma no agiudat su cliente, comente isetare, torrare a fàghere o costruire cosas chi nemos impreat.","noTip":1},{"id":"kaizen","g":"agile","word":"Megioru contìnuu","text":"Megiorare unu pagu semper cun càmbios piticos e regulares, e a pustis controllare chi ant agiudadu. Sas retro sunt una manera de lu fàghere. Si narat fintzas kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Iscuadra autoorganizada","text":"Un'iscuadra chi detzidet issa etotu comente fàghere su traballu, imbetzes de benner cumandada passu pro passu.","also":["autoorganizada","iscuadra autogestida"]},{"id":"crossfunc","g":"agile","word":"Iscuadra multifuntzionale","text":"Un'iscuadra chi tenet totu sas cumpetèntzias chi li serbint pro acabare su traballu issa etotu, comente disinnu, costrutzione e proas.","also":["cross-functional","multifuntzionale"]},{"id":"spike","g":"agile","word":"Spike","text":"Una chirca curtza, cun tempus fissu, pro rispòndere a una pregunta in antis de s'impinnare in su traballu beru.","also":["spikes"]},{"id":"rework","g":"agile","word":"Traballu torradu a fàghere","text":"Fàghere de nou unu traballu ca sa prima borta no fiat bennidu bene.","also":["rework","reworked","torrare a fàghere"]},{"id":"safe","g":"agile","word":"Agile a iscala (SAFe)","text":"Maneras de impreare s'Agile in medas iscuadras de un'organizatzione manna. SAFe (su Scaled Agile Framework) nde est un'esempru connotu.","also":["agile a iscala"]},{"id":"repo","g":"build","word":"Repo","text":"Sa cartella de su progetu cun su còdighe e totu s'istòria de sos commits. Podet istare in su computer tuo, in GitHub, o in ambos.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Una lìnea de traballu a banda in su còdighe, pro fàghere cambiamentos sena tocare sa versione printzipale.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Una fotografia sarvada de su còdighe, cun una nota curtza de su chi est cambiadu. Podes semper torrare a una.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Imbiare sas fotografias sarvadas tuas (commit) dae custu computer a sa còpia cumpartzida in lìnea, comente GitHub, gasi nde b'at una còpia de seguresa e sos àteros las podent pigare."},{"id":"merge","g":"build","word":"Merge","text":"Unire sos càmbios de una branch in un'àtera, de sòlitu torrende·los a sa versione printzipale."},{"id":"pr","g":"build","word":"Pull request","text":"Pedire chi sos càmbios de una branch siant controllados e unidos a sa versione printzipale. Unos cantos sitos lu giamant merge request.","also":["PR","PRs","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Riordinare su còdighe sena mudare su chi faghet: documentos prus piticos, nùmenes prus craros, mancu repetitziones."},{"id":"bug","g":"build","word":"Bug","text":"Calicuna cosa chi no andat comente depet.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Revisione de pares","text":"Unu segundu pàrigiu de ogros: una persone diferente dae s'autore controllat su traballu in antis chi lòmpat a tie, gasi passant prus pagos errores. In AI-gile un'àtera IA controllat cada carta.","also":["peer review","code review","revisione de su còdighe"]},{"id":"code","g":"build","word":"Còdighe","text":"Sas istrutziones iscritas chi nant a unu computer ite fàghere. Si narat fintzas còdighe sorgente.","also":["còdighe sorgente"],"noTip":1},{"id":"proglang","g":"build","word":"Limba de programmatzione","text":"Una limba pro iscriere còdighe, comente JavaScript, Python o Java. Cada una andat bene pro cumpitos diferentes.","also":["limbas de programmatzione"]},{"id":"developer","g":"build","word":"Isvilupadore (dev)","text":"Chie iscriet e càmbiat còdighe. Si narat fintzas programmadore o ingeniere de software.","also":["isvilupadore","isvilupadores","programmadore","programmadores","ingeniere de software"]},{"id":"software","g":"build","word":"Software","text":"Sos programmas chi girant in sos computer e in sos telèfonos, a diferèntzia de sas màchinas etotu (s'hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Abbreviatzione de aplicatzione: unu programma chi sa gente impreat pro fàghere calicuna cosa, in unu telèfonu, in unu computer o in unu navigadore web.","also":["apps","aplicatzione","aplicatziones"],"noTip":1},{"id":"webapp","g":"build","word":"App web","text":"Un'app chi funtzionat in unu navigadore web, duncas no b'at nudda de installare.","also":["apps web","aplicatzione web"]},{"id":"frontend","g":"build","word":"Front end","text":"Sa parte de un'app chi bides e incarcas: sas ischermadas, sos butones e sas paràulas, a s'ispissu in su navigadore tuo.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"Sa parte de un'app chi no si bidet, chi tenet sos datos e faghet su traballu cando incarcas calicuna cosa, comente controllare sa crae tua.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Traballare e in su front end e in su back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"Interfàtzia de s'utente (UI)","text":"Su chi una persone bidet e impreat in s'ischermu: disposta, butones, menù e testu.","also":["UI","interfàtzia de s'utente"]},{"id":"ux","g":"build","word":"Isperièntzia de s'utente (UX)","text":"Ite si proat impreende calicuna cosa: si est fàtzile, crara e piaghela, o cunfusa e lenta.","also":["UX","isperièntzia de s'utente"]},{"id":"accessibility","g":"build","word":"Atzessibilidade (a11y)","text":"Fàghere cosas chi totus podent impreare, fintzas persones chi non bident bene, non podent impreare su mouse o impreant unu letore de ischermu.","also":["a11y"]},{"id":"responsive","g":"build","word":"Disinnu adatabile","text":"Fàghere pàginas chi s'adatant e funtzionant bene in ischermos de cale si siat mannària, dae unu telèfonu a unu monitor mannu.","also":["adatabile"]},{"id":"designsys","g":"build","word":"Sistema de disinnu","text":"Unu kit cumpartzidu de colores, caràteres, butones e règulas, gasi cada ischermada paret e si cumportat de sa matessi manera.","also":["sistemas de disinnu"]},{"id":"architecture","g":"build","word":"Architetura","text":"Sa forma generale de unu sistema: cales sunt sas partes printzipales e comente faeddant intre issas."},{"id":"database","g":"build","word":"Base de datos (DB)","text":"Unu depòsitu ordinadu de informatziones, comente unu fògiu de càlculu meda potente chi s'app podet lèghere e cambiare.","also":["base de datos","bases de datos","DB"]},{"id":"schema","g":"build","word":"Ischema de sa base de datos","text":"S'organizatzione de una base de datos: cales tabellas de informatziones tenet e ite andat in cadauna.","also":["ischema"]},{"id":"sql","g":"build","word":"SQL","text":"Abbreviatzione de «structured query language»: sa limba impreada pro pregontare informatziones a medas bases de datos o pro las cambiare.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Datos","text":"Informatziones mantenidas dae unu computer, comente nùmenes, ordinatziones o impostatziones.","also":["dataset","datasets","grupu de datos"],"noTip":1},{"id":"server","g":"build","word":"Serbidore","text":"Unu computer semper allutu chi rispondet a sas dimandas de àteros computer, comente imbiare una pàgina web cando la visitas.","also":["serbidores"]},{"id":"client","g":"build","word":"Cliente","text":"Sa parte chi dimandat calicuna cosa, de sòlitu su navigadore o s'app tua, chi faeddat cun unu serbidore. In sos afares cheret nàrrere fintzas, simplemente, chie còmporat.","also":["clientes"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Abbreviatzione de «application programming interface»: unu menù fissu de dimandas chi unu programma podet fàghere a un'àteru, comente pregontare a unu servìtziu de su tempus sa previsione de oe.","also":["APIs","interfàtzia de programmatzione de aplicatziones"]},{"id":"endpoint","g":"build","word":"Puntu de atzessu (endpoint)","text":"Una voche de su menù de un'API: un'indiritzu web chi unu programma podet giamare pro otènnere o imbiare calicuna cosa.","also":["endpoint","endpoints","puntos de atzessu"]},{"id":"integration","g":"build","word":"Integratzione","text":"Collegare duos sistemas pro chi traballent impare, comente su negòtziu tuo chi imbiat sas ordinatziones a su software de contabilidade.","also":["integratziones"]},{"id":"webhook","g":"build","word":"Webhook","text":"Unu messàgiu chi unu sistema imbiat a un'àteru a sa sola, in su momentu chi capitat calicuna cosa, comente «pagamentu retzidu».","also":["webhooks"]},{"id":"library","g":"build","word":"Libreria","text":"Còdighe giai fatu chi un'àtera persone at iscritu e chi podes torrare a impreare imbetzes de l'iscriere tue.","also":["librerias"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Un'istrutura giai fata pro costruire un'app chi detzidet meda de comente est postu su còdighe, comente unu telàgiu de domo chi cumpletas.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Kit de isvilupu de software (SDK)","text":"Una cassa de ainas, còdighe e esempros pro costruire software pro una piataforma o unu servìtziu.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Dipendèntzia de software","text":"Una libreria o un'aina de sa cale su còdighe tuo tenet bisòngiu pro funtzionare. Las mantènnere agiornadas est importante pro sa seguresa.","also":["dipendèntzias de software"]},{"id":"package","g":"build","word":"Pachete","text":"Unu fascu de còdighe giai fatu chi podes installare e impreare in unu progetu.","also":["pachetes"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Gestore de pachetes","text":"Un'aina chi iscàrrigat e agiornat sos pachetes de sos cales dipendet su còdighe tuo. npm nde est unu de sos prus comunes.","also":["gestores de pachetes","npm"]},{"id":"git","g":"build","word":"Git","text":"S'aina prus impreada pro mantènnere s'istòria de sos càmbios a su còdighe, in forma de commit e de branch."},{"id":"github","g":"build","word":"GitHub","text":"Unu situ web chi tenet sos repo Git in lìnea, gasi sas iscuadras podent cumpartzire còdighe, rebìdere càmbios e sighire su traballu."},{"id":"vcs","g":"build","word":"Controllu de versiones","text":"Mantènnere un'istòria cumpleta de cada càmbiu a sos archìvios, gasi podes bìdere chie at cambiadu ite e torrare in segus si bi cheret. Git faghet custu.","also":["controllu de sorgente","sistema de controllu de versiones"]},{"id":"clone","g":"build","word":"Clone","text":"Fàghere una còpia cumpleta tua de unu repo, cun s'istòria, in su computer tuo.","also":["cloned","cloning","clonare","clonadu"]},{"id":"pull","g":"build","word":"Pull","text":"Pigare sos ùrtimos commit dae sa còpia cumpartzida (comente GitHub) e los pònnere in su computer tuo. Su cuntràriu de push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Branch printzipale","text":"Sa versione ufitziale de su còdighe dae sa cale totus traballant, a s'ispissu giamada main o master.","also":["main branch","master branch","branch master"]},{"id":"conflict","g":"build","word":"Cunflitu de merge","text":"Cando duos càmbios tocant sas matessi lìneas in manera diferente, e gasi su computer no los podet unire e una persone depet sèberare.","also":["merge conflict","merge conflicts","cunflitos de merge"]},{"id":"diff","g":"build","word":"Diff","text":"Una vista chi mustrat esatamente ite est cambiadu intre duas versiones: lìneas agiuntas e lìneas bogadas.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Sa còpia tua de su repo de un'àtera persone, chi podes cambiare sena tocare su suo.","also":["forks","forkadu"]},{"id":"script","g":"build","word":"Script","text":"Unu programma curtzu chi faghet unu traballu a sa sola, comente assentare archìvios o fàghere partire s'app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Trasformare su còdighe in calicuna cosa pronta a funtzionare, o su resultadu etotu, prontu a funtzionare.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compilare","text":"Tradùere su còdighe iscritu dae sas persones in una forma chi su computer podet esecutare deretu.","also":["compiladu","compiladore","compilende"]},{"id":"cli","g":"build","word":"Lìnia de cumandu (CLI)","text":"Una ventana de testu inue iscries istrutziones pro su computer imbetzes de incarcare. Si narat fintzas terminale.","also":["lìnea de cumandu","CLI","terminale"]},{"id":"config","g":"build","word":"Cunfiguratzione (config)","text":"Sas impostatziones chi controllant comente si cumportat su software, tenidas a banda dae su còdighe gasi sunt fàtziles de cambiare.","also":["config","cunfiguratzione"],"noTip":1},{"id":"envvar","g":"build","word":"Variabile de ambiente","text":"Un'impostatzione dada a unu programma cando partit, a s'ispissu impreada pro indiritzos o craes, gasi no sunt iscritas in su còdighe.","also":["variabiles de ambiente","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Chircare proite calicuna cosa non funtzionat, e l'acontzare.","also":["debug","debugadu"]},{"id":"pairing","g":"build","word":"Programmatzione in paja","text":"Duas persones (o una persone e una IA) chi traballant impare subra de su matessi còdighe, una chi iscriet e una chi controllat.","also":["pairing","pair programming"]},{"id":"docs","g":"build","word":"Documentatzione (docs)","text":"Ispiegatziones iscritas de comente funtzionat calicuna cosa o de comente si impreat.","also":["documentatzione","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Su primu archìviu de lèghere in unu repo: ite est su progetu e comente lu fàghere partire.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Sistema ereditadu","text":"Unu sistema prus betzu, ancora in impreu, chi est difìtzile de cambiare, a s'ispissu ca pagas persones lu cumprendent ancora.","also":["sistemas ereditados","còdighe ereditadu"]},{"id":"techdebt","g":"build","word":"Dèpidu tècnicu","text":"Solutziones a sa lestra chi oe sarvant tempus ma a pustis rendent prus lentos sos càmbios, comente unu prèstidu chi acumulat interessos. Su refactoring lu pagat a pagu a pagu.","also":["tech debt","technical debt","dèpidu tècnicu"]},{"id":"test","g":"test","word":"Test","text":"Una verìfica chi calicuna cosa funtzionet comente depet. Unas cantas proas las faghet su computer a sa sola cada borta chi su còdighe càmbiat; in àteras ses tue chi proas una carta acabada in antis de l'atzetare.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Est sa sigla de «quality assurance», garantzia de calidade: totu su chi si faghet pro s'assegurare chi su traballu siat giustu in antis chi andet in lìnea. In AI-gile cheret nàrrere sos controllos automàticos: cando sa QA est ruja, calicuna cosa at faddidu, e no podet andare in lìnea finas a cando no est acontzada.","also":["controllos de calidade","quality assurance"]},{"id":"testpile","g":"test","word":"Pila de proas","text":"Sas cartas acabadas chi isetant chi las proes, una a pustis de s'àtera. Atzeta·nde una o torra·la in segus cun una nota, e nde essit sa chi sighit.","also":["pilas de proas","test pile"]},{"id":"autotest","g":"test","word":"Proa automàtica","text":"Una verìfica chi su computer faghet a sa sola cada borta chi cambiat su còdighe, pro agatare sos errores chitzo.","also":["proas automàticas"]},{"id":"manualtest","g":"test","word":"Proa manuale","text":"Una persone chi proat su traballu a manu pro bìdere si si cumportat comente depet.","also":["proas manuales","proas a manu"]},{"id":"unittest","g":"test","word":"Proa de unidade","text":"Una verìfica automàtica pitica de unu cantu minore de còdighe, pigadu a sa sola.","also":["proas de unidade"]},{"id":"integtest","g":"test","word":"Proa de integratzione","text":"Una verìfica chi diversas partes funtzionent bene impare, no isceti una a sa borta.","also":["proas de integratzione"]},{"id":"endtoend","g":"test","word":"Proa de capu a pedes (E2E)","text":"Una proa chi faghet comente un'utente beru dae su cumintzu a s'acabu, comente registrare·si, comporare e pagare.","also":["E2E","capu a pedes","proas de capu a pedes"]},{"id":"uat","g":"test","word":"Proa de atzetatzione de s'utente (UAT)","text":"Sas persones chi ant dimandadu su traballu lu proant issas etotu e narant si faghet su chi lis serbit. Sa pila de proas de AI-gile est sa versione sua de custu.","also":["UAT","proa de atzetatzione"]},{"id":"regression","g":"test","word":"Regressione","text":"Calicuna cosa chi funtzionaiat ma s'est segada a pustis de unu càmbiu. Sas proas de regressione controllant chi sas cosas betzas funtzionent ancora.","also":["regressiones","proa de regressione","proas de regressione","test de regressione"]},{"id":"smoke","g":"test","word":"Proa de fumu","text":"Una verìfica meda lestra chi sas cosas printzipales funtzionent a su mancu, pro esempru deretu a pustis chi unu càmbiu andat in lìnea. Si fallit, firma·ti e controlla.","also":["proas de fumu"]},{"id":"exploratory","g":"test","word":"Proas esplorativas","text":"Proare su produtu a lìberu e lu puntzare in maneras diferentes, pro agatare problemas chi sas verìficas pianificadas dian lassare passare.","also":["exploratory test","exploratory tests","proa esplorativa"]},{"id":"testcase","g":"test","word":"Casu de proa","text":"Unu cenàriu iscritu de proare: sos passos, e ite depet capitare.","also":["casos de proa"]},{"id":"coverage","g":"test","word":"Cobertura de sas proas","text":"Cantu de su còdighe est controlladu dae proas automàticas. Prus est, prus est seguru de sòlitu, ma una cobertura arta, a sa sola, no pròvat chi funtzionet bene.","also":["cobertura","cobertura de su còdighe"]},{"id":"testdata","g":"test","word":"Datos de proa","text":"Informatziones de esempru inventadas, impreadas cando si proat, gasi non si mustrant sos detàllios privados de peruna persone bera.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Casu lìmite","text":"Una situatzione pagu comuna a sos lìmites, comente unu formulàriu bòidu o unu nùmene cun s'apòstrofu, inue sas cosas a s'ispissu si segant.","also":["casos lìmite"]},{"id":"happypath","g":"test","word":"Caminu allegru","text":"Su caminu normale inue totu andat bene. Unu bonu testing proat fintzas sos caminos inue sas cosas andant male."},{"id":"perftest","g":"test","word":"Proas de rendimentu","text":"Controllare cantu lestru est calicuna cosa e comente si cumportat suta de pressione.","also":["proa de rendimentu","proas de rendimentu"]},{"id":"loadtest","g":"test","word":"Proas de carrigu","text":"Controllare comente si cumportat unu sistema cando medas persones l'impreant a su matessi tempus.","also":["proa de carrigu","proas de carrigu"]},{"id":"sectest","g":"test","word":"Proas de seguresa","text":"Chircare sos puntos dèbiles chi podent permìtere a calicunu de impreare male unu sistema o de bìdere su chi no depet.","also":["proa de seguresa","proas de seguresa"]},{"id":"accesstest","g":"test","word":"Proas de atzessibilidade","text":"Controllare chi persones cun capatzidades diferentes podent impreare su produtu, fintzas cun unu letore de ischermu o cun isceti sa tastiera.","also":["proa de atzessibilidade"]},{"id":"linting","g":"test","word":"Linting","text":"Una verìfica automàtica chi agatat errores probàbiles e istile disordinadu in su còdighe, comente unu curretore ortogràficu pro programmas.","also":["linter","lint"]},{"id":"static","g":"test","word":"Anàlisi istàtica","text":"Controllare su còdighe pro agatare problemas leghende·lu in automàticu, sena lu fàghere girare.","also":["anàlisi istàtica de su còdighe"]},{"id":"flaky","g":"test","word":"Proa instàbile","text":"Una proa chi calicuna borta passat e calicuna borta fallit sena una resone crara, e gasi non bi podes cunfiare de su totu.","also":["flaky test","flaky tests","proas instàbiles"]},{"id":"repro","g":"test","word":"Riprodùere (repro)","text":"Fàghere capitare de nou unu bug a posta, sighende sos matessi passos, gasi si podet istudiare e acontzare. Iscriere custos passos est sa parte prus ùtile de unu raportu de bug.","also":["repro","reproduce","steps to reproduce","riprodùere","passos pro riprodùere"]},{"id":"severity","g":"test","word":"Gravidade","text":"Cantu est malu s'efetu de unu problema, dae unu fastìgiu piticu a totu firmu.","also":["livellu de gravidade"]},{"id":"deploy","g":"change","word":"Deploy","text":"Copiare una versione noa de su software in sos computer in ue girat, comente una còpia de proa o su servìtziu in lìnea."},{"id":"release","g":"change","word":"Lantzamentu","text":"Unu pachete de traballu acabadu, cun unu nòmine, chi andat in direta totu impare, cun pagas notas subra de su chi est cambiadu. 🚀 Lantzamentos iscriet sas notas dae sas cartas fatas.","also":["lantzamentos","release"]},{"id":"rollback","g":"change","word":"Rollback","text":"Torrare a s'ùrtima versione chi funtzionaiat cando una noa causat problemas. In AI-gile, Torra in segus riunit in una lista de controllu sos passos pro annullare iscritos in cada càmbiu.","also":["torrare in segus","annullare","roll back"]},{"id":"live","g":"change","word":"In direta","text":"Sa versione vera chi sa gente impreat, e no una còpia pro proare sas cosas. Sos programadores li narant fintzas produtzione.","also":["produtzione","live"],"noTip":1},{"id":"change","g":"change","word":"Muda","text":"Una muda programmada a calicuna cosa chi sa gente b'at bisòngiu, iscrita in antis: ite, pro ite, su rìsicu, cando e comente annullare·la. Incumintza·nde una cun 🔀 Pedi una muda.","also":["mudas","rechesta de muda","change request"],"noTip":1},{"id":"risk","g":"change","word":"Rìsicu","text":"Calicuna cosa chi diat pòdere andare male, cun unu puntègiu pro cantu est probàbile e cantu diat èssere grave. ⚠️ Risicos los mantenet in una lista sola, dae su puntègiu prus artu, ognunu cun una data pro torrare a bìdere.","also":["rìsicos","registru de sos rìsicos"]},{"id":"chgwin","g":"change","word":"Ventana de muda","text":"Sos momentos in ue sas mudas podent andare in direta, comente unu martis a sero tranchillu. Foras de una ventana, una carta de muda no si podet acabare, francu chi siat un'emergèntzia.","also":["ventanas de muda","change window"]},{"id":"gonogo","g":"change","word":"Andat / Non andat","text":"Unu controllu ùrtimu pròpiu in antis chi unu càmbiu andet in lìnea: cada persone chi depet aprovare narat Go o No go. Andat in antis isceti cando totus nant Go.","also":["go/no go","go-no-go","go / no go"]},{"id":"approval","g":"change","word":"Aprovatzione","text":"Isetare unu sì in antis chi su traballu incumintzet. Una carta chi pesat un'amigu, o una muda, isetat in ✅ Aprovatziones finas a cando no l'aprovas o no la refudas.","also":["aprovatziones"]},{"id":"quiettime","g":"change","word":"Tempus de calma","text":"Unu tretu de tempus, comente in una diretta, in una demo o de note, cando nudda andat in lìnea. Sas iscuadras sighint a traballare e a proare, ma s'andare in lìnea isetat finas a cando acabat. In àteros logos si narat blocu de sos càmbios (change freeze).","also":["tempos de calma","blocu de sas mudas","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Una manera de traballare inue sas persones chi costruint su software e cussas chi lu gestint traballant comente un'iscuadra sola, cun meda automatizatzione, gasi sos càmbios andant in lìnea a s'ispissu e in seguresa."},{"id":"cicd","g":"change","word":"CI/CD (integratzione e cunsigna contìnua)","text":"Sos càmbios de totus benint unidos a sa versione printzipale a s'ispissu e controllados in automàticu cada borta (integratzione contìnua), gasi su software est semper prontu a andare in lìnea incarchende unu butone (cunsigna contìnua).","also":["CI/CD","CI","CD","continuous integration","continuous delivery","integratzione contìnua","cunsigna contìnua"]},{"id":"contdeploy","g":"change","word":"Deploy contìnuu","text":"Unu passu in prus de sa cunsigna contìnua: cada càmbiu chi passat sas verìficas andat in lìnea a sa sola, sena butones de incarcare.","also":["continuous deployment","continuous deployments","deploy contìnuu"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"Sa serie automàtica de passos chi unu càmbiu faghet pro arribare in lìnea, comente build, proa e a pustis deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Ambiente","text":"Una còpia separada de su sistema pro unu fine ebbia, comente una pro costruire, una pro proare e cussa chi est in lìnea.","also":["ambientes"],"noTip":1},{"id":"devenv","g":"change","word":"Ambiente de isvilupu","text":"Sa còpia inue traballat un'isvilupadore, a s'ispissu in su computer suo, inue si segat calicuna cosa no faghet dannu a nemos.","also":["ambiente dev"]},{"id":"testenv","g":"change","word":"Ambiente de proa","text":"Una còpia separada de su sistema impreada isceti pro proare, gasi su servìtziu beru non benit tocadu.","also":["ambientes de proa"]},{"id":"staging","g":"change","word":"Staging","text":"Una ùrtima còpia fata comente sa chi est in lìnea, pro unu controllu finale in antis chi unu càmbiu andet in lìnea.","also":["ambiente de staging"]},{"id":"artifact","g":"change","word":"Artefatu de build","text":"S'archìviu o su pachete chi unu build produit, prontu a èssere sarvadu, controlladu o postu in lìnea.","also":["artefatos de build"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Una curretzione urgente posta in lìnea luego, foras de su pianu normale, ca calicuna cosa importante est segada.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"Un'agiornamentu piticu chi acontzat unu bug o serrat unu bucu de seguresa. Est importante aplicare luego sas patch de seguresa.","also":["patches","patch de seguresa","patches de seguresa"]},{"id":"version","g":"change","word":"Nùmeru de versione","text":"Un'eticheta comente 2.4.1 chi narat cale release tenes. A s'ispissu su primu nùmeru càmbiat pro sos càmbios mannos e s'ùrtimu pro sas curretziones piticas.","also":["nùmeros de versione","versionamentu semànticu"]},{"id":"relnotes","g":"change","word":"Notas de release","text":"Una lista curtza e simple de su chi est cambiadu in una release, pro sas persones chi l'impreant, cun curretziones e lìmites connotos. Si narat fintzas changelog.","also":["changelog","registru de càmbios"]},{"id":"flag","g":"change","word":"Interruptore de funtzionalidade","text":"Un'interruptore de allùghere e istudare pro una funtzionalidade, gasi su traballu nou podet andare in lìnea cuadu e èssere allutu (o torradu a istudare) sena una release noa.","also":["interruptores de funtzionalidade","feature flag","feature toggle"]},{"id":"rollfwd","g":"change","word":"Andare in antis","text":"Acontzare una release mala bogende luego una versione noa e curreta, imbetzes de torrare a sa betza.","also":["andende in antis","andadu in antis"]},{"id":"canary","g":"change","word":"Release canarinu","text":"Pònnere unu càmbiu in lìnea in antis pro unu grupu piticu, e pro totus isceti cando paret chi andat bene. Su nùmene benit dae sos canarinos chi sos minadores si portaiant suta terra pro los avertire de su perìgulu in antis.","also":["releases canarinos","canarinu"]},{"id":"bluegreen","g":"change","word":"Deploy blue-green","text":"Mantènnere duas còpias de su sistema in lìnea e passare sa zente a sa noa totu a una borta, gasi podes torrare deretu a sa betza si andat male.","also":["blue-green","deploy blue green"]},{"id":"zerodown","g":"change","word":"Deploy sena firmadas","text":"Pònnere una versione noa in lìnea sena chi su servìtziu si firmet mai pro sos utentes suos.","also":["zero downtime","deploy sena downtime"]},{"id":"chgenable","g":"change","word":"Gestione de sos càmbios","text":"Agiudare sos càmbios a andare bene: pesare s'arrisicu, otènnere s'aprovatzione giusta e sèberare unu tempus bonu. Si narat fintzas gestione de càmbios.","also":["gestione de càmbios"]},{"id":"cab","g":"change","word":"Cumitadu consultivu pro sos càmbios (CAB)","text":"Unu grupu chi bidet sos càmbios importantes e acordat si e cando podent andare in antis.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Càmbiu istandard","text":"Unu càmbiu de pagu arrisicu fatu semper de sa matessi manera giai proada, duncas est aprovadu in antis.","also":["càmbios istandard"]},{"id":"normchange","g":"change","word":"Càmbiu normale","text":"Unu càmbiu chi depet èssere controlladu e aprovadu in antis de lu fàghere.","also":["càmbios normales"]},{"id":"emergchange","g":"change","word":"Càmbiu de emergèntzia","text":"Unu càmbiu chi si depet fàghere luego pro acontzare o evitare unu problema grave, cun un'aprovatzione prus lestra comente cumbenit.","also":["càmbios de emergèntzia"]},{"id":"automation","g":"change","word":"Automatismu","text":"Fàghere fàghere a su computer, a sa sola, unu traballu chi si repitit, gasi est prus lestru e fatu semper de sa matessi manera.","also":["automatizadu"],"noTip":1},{"id":"infra","g":"change","word":"Infrastrutura","text":"Sas màchinas, sas retes e sos servìtzios subra de sos cales girat su software.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastrutura comente còdighe (IaC)","text":"Descrìere sos serbidores e sas impostatziones tuas in archìvios mantenidos cun su còdighe, gasi si podent torrare a costruire esatamente de sa matessi manera cada borta.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Afitare computer, archiviatzione e servìtzios dae unu frunidore mannu pro mèdiu de internet, imbetzes de tènnere sas màchinas tuas.","also":["the cloud","cloud computing","nue informàtica"]},{"id":"provider","g":"change","word":"Frunidore de cloud","text":"Un'impresa chi afitat potèntzia de càlculu pro mèdiu de internet, comente Amazon Web Services (AWS), Microsoft Azure o Google Cloud.","also":["cloud provider","cloud providers","frunidores de cloud"]},{"id":"hosting","g":"change","word":"Hosting","text":"Inue bivet e girat s'app o su situ web tuo pro chi sa gente bi potzat arribare, a s'ispissu afitadu dae un'impresa.","also":["ospitadu"]},{"id":"domain","g":"change","word":"Nùmene de domìniu","text":"S'indiritzu web chi sa gente iscriet, comente example.com. Lu afitas a annu, e duncas si depet rinnovare.","also":["nùmenes de domìniu","domìniu"]},{"id":"dns","g":"change","word":"DNS","text":"Abbreviatzione de «domain name system»: sa rubrica de internet, chi trasformat unu nùmene comente example.com in s'indiritzu de su computer giustu.","also":["sistema de nùmenes de domìniu"]},{"id":"container","g":"change","word":"Container","text":"Unu pachete serradu chi cuntenet un'app e totu su chi li serbit, gasi funtzionat de sa matessi manera in cale si siat computer. Docker est s'aina prus connota.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Màchina virtuale (VM)","text":"Unu computer fintu chi girat intro de unu computer beru, gasi una màchina manna podet funtzionare comente medas.","also":["VM","VMs","virtual machines","màchinas virtuales"]},{"id":"serverless","g":"change","word":"Serverless","text":"Fàghere girare còdighe sena dèpere curare serbidores: su frunidore lu faghet girare cando serbit e pagas isceti su chi impreas."},{"id":"lb","g":"change","word":"Ripartidore de carrigu","text":"Calicuna cosa chi partzit sos visitadores intre prus serbidores, pro chi perunu non abarret tropu carrigadu.","also":["ripartidores de carrigu"]},{"id":"cache","g":"change","word":"Cache","text":"Unu depòsitu a manu de sos resultados reghentes, tentu a curtzu, gasi sa matessi cosa no si depet torrare a pigare o a calculare. Si l'isbòidas, podes acontzare pàginas chi parent betzas.","also":["caches","caching","in cache"]},{"id":"cdn","g":"change","word":"Rete de distributzione de cuntenutos (CDN)","text":"Una rete de serbidores in totu su mundu chi tenent còpias de sas pàginas e de sas immàgines tuas a curtzu de sos visitadores, gasi si carrigant luego.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Migratzione","text":"Tramudare datos o sistemas dae una cunfiguratzione betza a una noa, o cambiare cun cura comente est organizada una base de datos.","also":["migratziones","migratzione de base de datos"]},{"id":"service","g":"run","word":"Servìtziu","text":"Calicuna cosa chi as fraigadu e chi sa gente b'at bisòngiu, comente unu situ o un'app, curada pro chi sigat a funtzionare. Sinna “Custu progetu est unu servìtziu” e nara ite oferit, chie l'impreat e chie est de guàrdia.","also":["servìtzios"]},{"id":"uptimepct","g":"run","word":"Tempus in lìnea","text":"Pro cantu tempus unu servìtziu funtzionat, de sòlitu in pertzentuale. Su 99,9% permitit ancora a pagu a pagu 43 minutos de firmu a su mese.","also":["pertzentuale de tempus in lìnea"]},{"id":"uptime","g":"run","word":"Controllu de funtzionamentu","text":"Unu controllu automàticu, ogni pagos minutos, chi su servìtziu tuo rispondet galu. Si faddit unas cantas bortas de sighidu, AI-gile aberit a sa sola una carta de incidente.","also":["uptime","controllos de uptime"]},{"id":"statuspage","g":"run","word":"Pàgina de istadu","text":"Una pàgina pùblica chi mustrat si unu servìtziu funtzionat (birde, arantzu o ruju) cun s'ùrtimu agiornamentu, gasi sa gente chi l'impreat podet controllare imbetzes de pregontare.","also":["pàginas de istadu","status page"]},{"id":"desk","g":"run","word":"Banchu de assistèntzia","text":"Su logu in ue arribant sas dimandas e sas segnalatziones de sa gente chi impreat su servìtziu tuo. AI-gile ponet ognuna comente pedidu, incidente o idea, e lu narat cando paret una cosa giai segnalada.","also":["banchos de assistèntzia","banchu","service desk","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Pedidu de servìtziu","text":"Calicunu chi pedit una cosa normale, comente unu contu nou o unu pagu de agiudu, imbetzes de segnalare chi calicuna cosa est segada. Isetat su turnu suo; un'incidente passat in antis.","also":["pedidos de servìtziu","pedidu"]},{"id":"incident","g":"run","word":"Incidente","text":"Calicuna cosa segada o chi no funtzionat bene pro sas persones chi l'impreant como, comente su situ web firmu o meda lentu. Una carta 🔥 incidente brincat sa cua: torrare a la fàghere funtzionare benit in antis de totu.","also":["incidentes","guastu"]},{"id":"major","g":"run","word":"Incidente mannu","text":"Un'incidente grussu: medas persones tocadas, o dinare o datos in perìculu. Unu butone ponet totu sas iscuadras in subra (isciamu), ischidat chie est de guàrdia e pedit un'agiornamentu de istadu ogni 30 minutos.","also":["incidentes mannos","major incident"]},{"id":"oncall","g":"run","word":"De guàrdia","text":"Èssere sa persone chi rispondet cando calicuna cosa si segat, fintzas de note. Ogni servìtziu tenet unu cumpàngiu de iscuadra de guàrdia, chi est ischidadu primu pro sos incidentes suos.","also":["guàrdia","on call","on-call"]},{"id":"replyby","g":"run","word":"Tempus de risposta","text":"Cantu tempus una carta podet isetare una prima risposta, pro esempru un'ora pro un'incidente. A pustis tenet un'orologiu ruju, gasi nudda abarrat ismentigadu a sa muda. Li narant fintzas obietivu de risposta.","also":["tempos de risposta","obietivu de risposta"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Un'ograda curtza a segus a pustis de un'incidente: ite est sutzèdidu, ite at agiudadu e ite cambiare, sena dare sa culpa a nemos. Un'incidente no si podet serrare sena unu post-mortem.","also":["post-mortems","postmortem","revisione a pustis de s'incidente"]},{"id":"problem","g":"run","word":"Problema","text":"Sa causa cuada in segus de unu o prus incidentes. Una carta 🧩 problema agrupat sos incidentes chi sighint a torrare, gasi sa causa est agatada e acontzada pro semper.","also":["problemas"],"noTip":1},{"id":"rootcause","g":"run","word":"Causa de fundu","text":"Su motivu beru pro ite una cosa s'est segada, e no isceti su chi as bidu andende male. Acontza sa causa de fundu e s'incidente no torrat prus.","also":["causas de fundu","root cause"]},{"id":"workaround","g":"run","word":"Soluzione provisòria","text":"Una manera de mantènnere sas cosas in funtzione finas a cando s'acontzu beru est prontu, comente torrare a aviare una cosa cando s'arresta. Est iscrita in sa carta de su problema, gasi nemos la depet torrare a agatare.","also":["soluziones provisòrias","workaround"]},{"id":"knownerror","g":"run","word":"Errore connotu","text":"Unu problema cun una causa connota ma ancora no acontzadu, a s'ispissu cun una solutzione provisòria iscrita. 🧩 Errores connotos los elencat, gasi totus impreant sa solutzione provisòria imbetzes de torrare a chircare.","also":["errores connotos","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Istrutziones passu pro passu pro acontzare unu tipu de problema connotu, gasi si faghet semper a sa matessi manera, a lestru. A pustis de un'incidente mannu, s'iscuadra nde podet propònnere unu pro chi tue nde des s'OK.","also":["runbooks","istrutziones operativas"]},{"id":"ci","g":"run","word":"Elementu de cunfiguratzione","text":"Una cosa de sa cale dipendet su servìtziu tuo, comente unu serbidore, unu domìniu, unu tzertificadu, una crae o unu fornidore. 🗂️ Elementos de cunfiguratzione los elencat pro ogni servìtziu, gasi bides ite tocat un'incidente e ite tocat a rinnovare o a nde fàghere una còpia de seguresa.","also":["elementos de cunfiguratzione"]},{"id":"expiry","g":"run","word":"Data de iscadèntzia","text":"Sa data in ue calicuna cosa no funtzionat prus si no est rinnovada, comente su tzertificadu de seguresa de unu situ web o s'indiritzu suo. AI-gile sighit custas datas e faghet una carta pro rinnovare cadauna 30 dies in antis, gasi nudda si firmat a s'ispensada.","also":["datas de iscadèntzia","iscadèntzia","controllu de iscadèntzias"]},{"id":"backup","g":"run","word":"Còpia de seguresa","text":"Una còpia sarvada de sos datos tuos de prima, pro la pòdere impreare si carchi cosa si perdet o si guastat. AI-gile faghet ogni die una còpia de seguresa de sos tabellones tuos.","also":["còpias de seguresa","backup","backups"]},{"id":"restore","g":"run","word":"Riprìstinu","text":"Torrare a pònnere sos datos dae una còpia de seguresa. Una còpia contat a beru isceti cando ischis chi si podet riprìstinare, duncas balet sa pena de lu proare onni tantu.","also":["riprìstina","riprìstinadu","restore"]},{"id":"svcreview","g":"run","word":"Revisione de su servìtziu","text":"Un'ograda a pustis a unu mese de unu servìtziu: incidentes abertos e acontzados, cantu a lestru sa gente at tentu una risposta, funtzionamentu e token impreados. Sa Revisione mensile lu mustrat pro ogni servìtziu.","also":["revisiones de su servìtziu","revisione mensile","revisiones mensiles"]},{"id":"accessreview","g":"run","word":"Revisione de atzessu","text":"Controllare cada 90 dies chie podet ancora intrare: ligòngios de cumpartzidura, rolos de sos amigos, e craes e segretos sarvados. Cadaunu lu mantenes o lu bogas, gasi s'atzessu betzu no abarrat.","also":["revisiones de atzessu"]},{"id":"improvements","g":"run","word":"Lista de megioramentos","text":"Totu su chi s'iscuadra at detzìdidu de megiorare, in unu logu ebbia: cussìgios de sa retro, atziones de sas revisiones e acontzos de problemas, ognunu cun s'istadu suo. Dda agatas in 📈 Megioramentos.","also":["listas de megioramentos","megioramentos"]},{"id":"tokencap","g":"run","word":"Lìmite de token","text":"Unu lìmite mensile de sos token chi sos agentes de unu servìtziu podent impreare. A su 80% retzis un'avisu; a su 100% su traballu issoro in segundu pianu isetat finas a su mese chi benit o finas a cando no artzias su lìmite.","also":["lìmites de token","lìmite mensile de token"]},{"id":"svcmgmt","g":"run","word":"Gestione de servìtzios","text":"Totu su chi serbit pro mantènnere unu servìtziu ùtile e in funtzione pro sas persones chi bi contant, die cun die.","also":["gestire unu servìtziu"]},{"id":"itil","g":"run","word":"ITIL","text":"Una guida meda impreada pro una bona gestione de servìtzios, chi tratat cosas comente incidentes, problemas e càmbios. A primu su nùmene cheriat nàrrere IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Gestione de servìtzios IT (ITSM)","text":"Gestire sa tecnologia comente unu servìtziu pro sas persones, cun maneras craras de tratare dimandas, incidentes, càmbios e megioros.","also":["ITSM"]},{"id":"managed","g":"run","word":"Servìtziu gestidu","text":"Unu servìtziu chi un'àteru gestit e curat pro tie, cun un'acordu subra de cantu bene depet funtzionare.","also":["servìtzios gestidos"]},{"id":"svcowner","g":"run","word":"Mere de su servìtziu","text":"Sa persone chi rispondet de unu servìtziu in totale: cantu bene funtzionat, ite costat e comente megiorat.","also":["meres de su servìtziu"]},{"id":"sla","g":"run","word":"Acordu de livellu de servìtziu (SLA)","text":"Una promissa iscrita a sos clientes subra de cantu bene at a funtzionare unu servìtziu, comente «in lìnea su 99,9% de su tempus» o «risposta intro de un'ora», a s'ispissu cun unu rimborsu si no est rispetada.","also":["SLA","SLAs","acordu de livellu de servìtziu"]},{"id":"slo","g":"run","word":"Obietivu de livellu de servìtziu (SLO)","text":"Sa meta de s'iscuadra etotu pro cantu bene depet funtzionare unu servìtziu in unu perìodu, de sòlitu unu pagu prus severa de su SLA, pro prudèntzia.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Indicadore de livellu de servìtziu (SLI)","text":"Sa mesura reale chi cunfrontas cun una meta, comente sa parte de visitas chi si sunt carrigadas bene.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Disponibilidade","text":"Si sas persones podent impreare unu servìtziu cando nde tenent bisòngiu, a s'ispissu mesuradu comente tempus in lìnea.","also":["high availability","arta disponibilidade"]},{"id":"downtime","g":"run","word":"Tempus firmadu","text":"Su tempus in ue unu servìtziu non funtzionat o est istudadu, pianificadu o nono.","also":["tempus de firmada"]},{"id":"errorbudget","g":"run","word":"Budget de errores","text":"Sa cantidade pitica de faddinas chi s'obietivu de afidabilidade permitit. Finas a cando nde abarrat, podes pigare arriscos cun sos càmbios; cando est acabada, andas prus a bellu.","also":["budgets de errores"]},{"id":"outage","g":"run","word":"Interrutzione","text":"Unu tempus in ue unu servìtziu est firmu o segadu male pro sos utentes suos.","also":["interrutziones"]},{"id":"degraded","g":"run","word":"Degradadu","text":"Funtzionat, ma male: lentu, o cun calicuna parte chi non andat.","also":["servìtziu degradadu"]},{"id":"monitoring","g":"run","word":"Monitoragiu","text":"Controllare unu servìtziu in automàticu e semper, gasi sos problemas si notant, mègius ancora in antis chi sos utentes los notent.","also":["monitoradu"]},{"id":"observability","g":"run","word":"Osservabilidade","text":"Cantu bene podes cumprèndere dae foras ite est capitende intro de unu sistema, impreende sos log, sos nùmeros e sas tràtzias suas.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"Unu diàriu chi unu programma tenet de ite est faghende, impreadu pro cumprendere ite est andadu male.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Tràtzia","text":"Unu registru de comente una dimanda passat pro sas partes diferentes de unu sistema, passu pro passu, chi mustrat inue at pèrdidu tempus.","also":["traces","tracing","tràtzias"]},{"id":"latency","g":"run","word":"Latèntzia","text":"Cantu tempus bi ponet calicuna cosa a rispòndere, comente s'isetu intre su clic e sa pàgina chi cumparet."},{"id":"alert","g":"run","word":"Allarme","text":"Unu messàgiu automàticu chi calicuna cosa tenet bisòngiu de atentzione, comente su situ web chi no rispondet.","also":["alerts","alerting","allarmes"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Istracchesa de allarmes","text":"Cando b'at tantos allarmes chi sa gente cumintzat a non los cunsiderare prus, fintzas cussos importantes.","also":["istracchesa de allarme"]},{"id":"dashboard","g":"run","word":"Pannellu de controllu","text":"Un'ischermada chi mustrat sos nùmeros e sos istados prus importantes a unu sinnu de ogru.","also":["pannellos de controllu"],"noTip":1},{"id":"paging","g":"run","word":"Giamada urgente","text":"Giamare o ischidare luego sa persone de turnu pro unu problema.","also":["giamadu"]},{"id":"escalation","g":"run","word":"Escalation","text":"Giamare calicunu cun prus cumpetèntzia o autoridade cando unu problema non si podet resòlvere a su livellu de como, o non a lestru bastante.","also":["escalate","escalated","escalations"]},{"id":"triage","g":"run","word":"Triage","text":"Ordinare lestru sos problemas chi arribant segundu cantu sunt urgentes e importantes, gasi su peus benit gestidu in antis.","also":["triaged"]},{"id":"impact","g":"run","word":"Impatu","text":"Cantu calicuna cosa tocat a sas persones: cantas, e cantu male.","noTip":1},{"id":"urgency","g":"run","word":"Urgèntzia","text":"Cantu luego si depet tratare calicuna cosa. Impatu e urgèntzia impare detzident sa prioridade.","noTip":1},{"id":"plevels","g":"run","word":"Livellos de prioridade (P1, P2…)","text":"Etichetas chi narant cantu est urgente unu problema. P1 est su prus grave e cheret atziones deretu.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Cua de tickets","text":"Sa lista de dimandas e incidentes chi isetant de èssere pigados.","also":["cuas de tickets"]},{"id":"tiers","g":"run","word":"Primu livellu e segundu livellu","text":"Livellos de assistèntzia: su primu livellu pigat sa giamada e acontzat sas cosas simples; su segundu tenet cumpetèntzias prus profundas pro cussas prus difìtziles. Si narant fintzas tier 1 e tier 2.","also":["primu livellu","segundu livellu","assistèntzia de primu livellu","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Cumandante de s'incidente","text":"S'ùnica persone chi ghiat sa risposta a un'incidente, gasi totus ischint chie detzidet e chie faghet ite.","also":["cumandantes de s'incidente"]},{"id":"responsetime","g":"run","word":"Tempus de risposta","text":"Cantu tempus passat in antis chi calicunu pigat pro sa prima borta una dimanda o un'incidente.","also":["tempos de risposta"]},{"id":"resolution","g":"run","word":"Tempus de resolutzione","text":"Cantu tempus bi cheret pro resòlvere de su totu una dimanda o un'incidente, dae sa segnalatzione finas a cando est acontzadu.","also":["resolution times","time to resolve","tempos de resolutzione"]},{"id":"mttr","g":"run","word":"Tempus mèdiu de recuperu (MTTR)","text":"In mèdia, cantu tempus bi cheret pro torrare a fàghere funtzionare unu servìtziu a pustis chi si segat. MTTR podet chèrrere nàrrere cosas unu pagu diferentes, duncas nara ite mesuras.","also":["MTTR","tempus mèdiu de ripristinu"]},{"id":"mtbf","g":"run","word":"Tempus mèdiu intre faddinas (MTBF)","text":"In mèdia, cantu tempus funtzionat unu servìtziu in antis chi calicuna cosa si seghet.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Base de datos de gestione de sa cunfiguratzione (CMDB)","text":"Sa lista de totu sos elementos de cunfiguratzione tuos e comente sunt collegados, gasi bides ite dipendet dae ite.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Cale si siat cosa de valore chi tenes o pagas pro fàghere funtzionare su servìtziu, comente unu portàtile, una lissèntzia de software o unu domìniu.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Pianificatzione de sa capatzidade","text":"Assegurare chi b'at a àere bastante potèntzia de computer, archiviatzione e persones pro su chi at a bènnere.","also":["pianu de capatzidade"]},{"id":"scaling","g":"run","word":"Iscalamentu","text":"Afrontare prus utentes dende a una màchina prus potèntzia (iscalamentu a artu) o agiunghende àteras màchinas (iscalamentu a largu).","also":["iscalare a artu","iscalare a largu","iscalamentu a artu","iscalamentu a largu"]},{"id":"bcp","g":"run","word":"Continuidade operativa","text":"Pianos pro mantènnere in funtzione sas cosas importantes cando calicuna cosa manna andat male, comente pèrdere un'ufìtziu, unu frunidore crae o sos computer.","also":["pianu de continuidade operativa"]},{"id":"dr","g":"run","word":"Recuperu dae disastros (DR)","text":"Su pianu e sas ainas pro torrare a pònnere in funtzione unu servìtziu a pustis de calicuna cosa grave, comente pèrdere unu data center intreu.","also":["recuperu dae disastros"]},{"id":"rto","g":"run","word":"Obietivu de tempus de recuperu (RTO)","text":"Su tempus prus longu chi unu servìtziu podet abarrare firmu a pustis de unu disastru, in antis chi depat torrare a funtzionare.","also":["RTO"]},{"id":"rpo","g":"run","word":"Obietivu de puntu de recuperu (RPO)","text":"Cantos datos reghentes ti podes permìtere de pèrdere, mesurados in tempus. Unu RPO de un'ora cheret nàrrere còpias de seguresa a su mancu cada ora.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Ridondàntzia","text":"Tènnere ricàmbios prontos, comente unu segundu serbidore, gasi una faddina no firmat su servìtziu.","also":["ridondante"]},{"id":"failover","g":"run","word":"Failover","text":"Passare a sa sola a unu sistema de ricàmbiu cando cussu de sòlitu fallit.","also":["fail over"]},{"id":"spof","g":"run","word":"Puntu sìngulu de faddina","text":"Una parte chi, si si segat, si leat totu in fatu, ca non b'at ricàmbiu.","also":["puntos sìngulos de faddina","SPOF"]},{"id":"maintwin","g":"run","word":"Ventana de manutentzione","text":"Unu tempus pianificadu cando unu servìtziu podet èssere firmadu o lentu pro sa manutentzione, annuntziadu in antis a sos utentes.","also":["ventanas de manutentzione","manutentzione pianificada"]},{"id":"handover","g":"run","word":"Cunsigna de traballu","text":"Passare traballu, connoschèntzia e responsabilidade a un'àtera persone o iscuadra, gasi nudda si perdet.","also":["handover","handovers","cunsignas de traballu"]},{"id":"kb","g":"run","word":"Base de connoschèntzia","text":"Una colletzione de artìculos de agiudu e de rispostas, pro sos utentes e pro s'iscuadra.","also":["bases de connoschèntzia"]},{"id":"csat","g":"run","word":"Cuntentesa de sos clientes (CSAT)","text":"Unu votu dadu dae sos utentes chi narat cantu sunt istados cuntentos, a s'ispissu pregontadu a pustis chi una dimanda est serrada.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Frunidore","text":"Un'impresa de foras de sa cale dipendes, comente su frunidore de hosting. Si narat fintzas vendor o tertza parte.","also":["suppliers","vendor","vendors","third party","frunidores"],"noTip":1},{"id":"retire","g":"run","word":"Ritiru de su servìtziu","text":"Istudare unu servìtziu pro semper, in seguresa: avisare sos utentes suos, gestire sos datos e s'atzessu suos, e firmare sos costos.","also":["retiring a service","service retirement"]},{"id":"eol","g":"run","word":"Fine de vida (EOL)","text":"Cando unu produtu non retzit prus agiornamentos o assistèntzia dae chie l'at fatu, e duncas si depet sostituire.","also":["EOL","fine-vida"]},{"id":"cybersec","g":"sec","word":"Seguresa informàtica","text":"Protègere sistemas e datos dae intrusiones, furas o dannos.","also":["cyber security","cybersecurity"]},{"id":"authn","g":"sec","word":"Autenticatzione","text":"Controllare chie est una persone, de sòlitu cun una crae o unu còdighe. A s'ispissu abbreviadu authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Autorizatzione","text":"Controllare ite una persone podet fàghere a pustis chi ischis chie est. A s'ispissu abbreviadu authz.","also":["authz","autorizatzione"]},{"id":"mfa","g":"sec","word":"Autenticatzione a prus fatores (MFA)","text":"Intrare cun duas o prus proas, comente una crae e unu còdighe in su telèfonu. Si narat fintzas autenticatzione a duos fatores (2FA).","also":["MFA","2FA","duos fatores","autenticatzione a duos fatores"]},{"id":"sso","g":"sec","word":"Intrada ùnica (SSO)","text":"Intrare una borta sola pro pòdere atzèdere a medas sistemas, comente impreare su contu de traballu in totue.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Gestore de craes","text":"Un'app chi creat craes fortes e las regordat pro tie.","also":["gestores de craes"]},{"id":"secret","g":"sec","word":"Segretu","text":"Una paràula segreta, una crae o un'àteru còdighe privadu chi unu programma impreat pro intrare in calicuna cosa. No si depet cumpartzire mai nen iscriere in su còdighe.","also":["segretos"],"noTip":1},{"id":"apikey","g":"sec","word":"Crae API","text":"Unu còdighe segretu chi lassat unu programma impreare s'API de un'àteru servìtziu, e mustrat chie lu impreat (e lu pagat).","also":["craes API"]},{"id":"accesstoken","g":"sec","word":"Token de atzessu","text":"Unu permissu temporàneu chi pròvat chi unu programma podet intrare, gasi no tenet bisòngiu de sa crae tua cada borta. No est sa matessi cosa de unu token IA.","also":["tokens de atzessu"]},{"id":"encryption","g":"sec","word":"Cifradura","text":"Ammesturare sas informatziones gasi chi isceti chie tenet sa crae giusta las potzat lèghere.","also":["cifradu","cifrare"]},{"id":"https","g":"sec","word":"HTTPS","text":"Su caminu seguru chi faghent sas pàginas web, mustradu dae su lucheto in su navigadore, gasi nemos in mesu las podet lèghere o cambiare."},{"id":"cert","g":"sec","word":"Tzertificadu SSL/TLS","text":"Una carta de identidade digitale chi permitit a unu situ web de proare chie est e de impreare HTTPS. Iscadit, e duncas si depet rinnovare.","also":["tzertificadu TLS","tzertificadu SSL","tzertificadu","tzertificados"]},{"id":"permissions","g":"sec","word":"Permissos","text":"Sas règulas chi narant chie podet bìdere o cambiare ite.","also":["permissu"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Mancu privilègiu possìbile","text":"Dare a cada persone o programma isceti s'atzessu chi li serbit a beru, e isceti finas a cando nde tenet bisòngiu.","also":["printzìpiu de su mancu privilègiu"]},{"id":"rbac","g":"sec","word":"Controllu de atzessu pro rolos (RBAC)","text":"Dare atzessu pro rolu, comente visore o editore, imbetzes de persone pro persone.","also":["RBAC","atzessu pro rolos"]},{"id":"vuln","g":"sec","word":"Vulnerabilidade","text":"Una debilesa chi calicunu diat pòdere impreare pro intrare o fàghere dannu.","also":["vulnerabilidades"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Una debilesa chi sos atacantes connoschent in antis chi sos creadores apant àpidu tempus de l'acontzare.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Software dannosu, comente sos virus, fatu pro dannigare, ispiare o furare."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware chi blocat sos archìvios tuos e pedit dinare pro los isblocare. Sas còpias de seguresa bonas sunt sa difesa mègius.","also":["atacu ransomware"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Messàgios falsos chi chircant de ti ingannare pro ti fàghere dare craes o dinare, o abèrrere calicuna cosa dannosa.","also":["email de phishing","emails de phishing"]},{"id":"socialeng","g":"sec","word":"Ingegneria sotziale","text":"Ingannare sas persones, imbetzes de sos computer, pro otènnere atzessu, comente una giamada falsa de s'«assistèntzia IT»."},{"id":"firewall","g":"sec","word":"Firewall","text":"Una ghàrdia chi detzidet cale tràficu de rete podet intrare o essire.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Abbreviatzione de «virtual private network»: unu collegamentu privadu e tzifradu pro mèdiu de internet, a s'ispissu impreadu pro intrare in seguresa in sos sistemas de traballu.","also":["rete privada virtuale"]},{"id":"ddos","g":"sec","word":"Negatzione de servìtziu (DoS, DDoS)","text":"Prènnere unu servìtziu de tràficu falsu, tantu chi sas persones beras non lu podent impreare. DDoS cheret nàrrere chi su tràficu benit dae medas computer a su matessi tempus.","also":["DoS","DDoS","negatzione de servìtziu","atacu DDoS"]},{"id":"pentest","g":"sec","word":"Proa de penetratzione (pen test)","text":"Pagare espertos fidados pro chi proent a intrare a fortza, gasi sas debilesas si agatant in antis chi las agatent sos atacantes beros.","also":["pen test","proas de penetratzione","pentest"]},{"id":"audit","g":"sec","word":"Auditu de seguresa","text":"Unu controllu atentu de cantu bene calicuna cosa est protègida, cunfrontende·la cun una lista de bonas pràticas.","also":["auditos de seguresa"]},{"id":"threatmodel","g":"sec","word":"Modellu de minatzas","text":"Pensare a fundu chie podet atacare calicuna cosa, comente, e ite dias fàghere pro los firmare.","also":["modellu de minatzas","modellare sas minatzas"]},{"id":"breach","g":"sec","word":"Violatzione de datos","text":"Cando informatziones privadas lòmpent a persones chi no las depent tènnere, o benint pèrdidas o cambiadas sena permissu.","also":["data breach","data breaches","violatziones de datos"]},{"id":"pii","g":"sec","word":"Datos personales","text":"Cale si siat informatzione subra de una persone chi si podet identificare, comente unu nùmene, un'indiritzu de email o unu logu. Si narat fintzas PII.","also":["PII","informatziones chi identificant sa persone"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Sa lege europea subra de sos datos personales (su Regnu Unidu tenet sa versione sua): colli isceti su chi serbit, mantene·los in seguresa, e permite a sas persones de bìdere o de cantzellare sos suos.","also":["Regulamentu generale subra de sa protetzione de sos datos"]},{"id":"dataprot","g":"sec","word":"Protetzione de sos datos","text":"Tènnere cura de sos datos personales in sa manera giusta e in rispetu de sa lege.","also":["lege subra de sa protetzione de sos datos"]},{"id":"privacypolicy","g":"sec","word":"Polìtica de riservadesa","text":"Una pàgina pùblica chi narat cales datos personales collis, proite, e ite nde faghes.","also":["privacy statement","privacy notice","declaratzione de riservadesa","avisu de riservadesa"]},{"id":"consent","g":"sec","word":"Consensu","text":"Unu «eja» craru e lìberu de una persone a s'impreu de sos datos suos in una manera particulare. Lu podet ritirare cando cheret.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Un'archìviu piticu chi unu situ web sarvat in su navigadore tuo pro si regordare cosas, comente s'atzessu giai fatu. Unos cantos tenent bisòngiu in antis de su consensu tuo.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Minimizatzione de sos datos","text":"Collire e mantènnere isceti sos datos personales chi serbint beru pro su traballu.","also":["minimizatzione de sos datos"]},{"id":"retention","g":"sec","word":"Cunservatzione de sos datos","text":"Cantu tempus sos datos benint mantenidos in antis de èssere cantzellados. Los mantènnere no prus de su netzessàriu est prus seguru e a s'ispissu est sa lege.","also":["perìodu de cunservatzione"]},{"id":"anon","g":"sec","word":"Anonimizatzione","text":"Cambiare sos datos gasi chi, in manera resonàbile, nemos si potzat prus identificare dae issos.","also":["anonimizadu","datos anònimos"]},{"id":"pseudo","g":"sec","word":"Pseudonimizatzione","text":"Cambiare nùmenes e àteros detàllios cun còdighes, cun una crae tenta a banda pro los torrare a collegare. Sunt ancora datos personales.","also":["pseudonimizadu"]},{"id":"dpa","g":"sec","word":"Acordu de tratamentu de sos datos (DPA)","text":"Unu cuntratu chi narat comente unu frunidore podet gestire datos personales pro contu tuo.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Valutatzione de s'impatu subra de sa protetzione de sos datos (DPIA)","text":"Un'esàmene atentu, in antis de cumintzare, de comente unu pianu pro impreare datos personales podet tocare sas persones e de comente ridùere sos arriscos.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Registru de auditu","text":"Unu registru de chie at fatu ite e cando, gasi sas atziones si podent controllare a pustis.","also":["registros de auditu","tràtzia de auditu"]},{"id":"compliance","g":"sec","word":"Cunformidade","text":"Sighire sas leges, sas règulas e sos istandard chi ti tocant, e pòdere mustrare chi lu faghes.","also":["cunforme"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Un'istandard internatzionale connotu pro gestire sa seguresa de sas informatziones. Sas impresas si podent fàghere tzertificare.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Unu raportu americanu, verificadu dae auditores esternos, chi mustrat chi un'impresa tenet cura de sos datos de sos clientes in sa manera giusta.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agente","text":"Una IA chi traballat a sa sola in unu cumpitu: leghet su còdighe, faghet càmbios, esecutat controllos e ti torrat informe. Su traballu suo benit controlladu su matessi.","also":["agentes"]},{"id":"token","g":"ai","word":"Token","text":"Sos cantigheddos de testu chi una IA leghet e iscriet, de a pagu a pagu tres cuartos de paràula cadaunu. S'impreu de s'IA si contat in token, duncas prus pagos token lassant de prus de su pianu tuo.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Unu cumandu piticu chi girat a sa sola in unu momentu fissu, pro esempru cando cumintzat una sessione IA, gasi s'iscuadra intendet sos cummentos tuos.","also":["hooks"]},{"id":"ai","g":"ai","word":"Intelligèntzia artifitziale (IA)","text":"Sistemas informàticos chi faghent cosas chi de sòlitu pensamus chi cherent una persone, comente iscriere, rispòndere a preguntas o reconnòschere immàgines.","also":["IA","AI","intelligèntzia artifitziale"],"noTip":1},{"id":"ml","g":"ai","word":"Aprendimentu automàticu (ML)","text":"Una manera de fàghere imparare a sos computer schemas dae medas esempros, imbetzes de lis dare règulas esatas.","also":["machine learning","aprendimentu automàticu"]},{"id":"model","g":"ai","word":"Modellu","text":"Su «cherbeddu» allenadu de unu sistema IA, costruidu imparende dae cantidades mannas de esempros. Sos modellos sunt diferentes in abilidade, lestresa e prètziu.","also":["modellos","modellu IA"],"noTip":1},{"id":"llm","g":"ai","word":"Modellu de limba mannu (LLM)","text":"Unu modellu IA allenadu cun cantidades mannas de testu, gasi podet lèghere e iscriere testos.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"IA generativa","text":"IA chi creat cosas noas, comente testu, immàgines o còdighe, imbetzes de isceti ordinare·las o riconnòschere·las.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Unu programma cun su cale faeddas in limba de ònnia die, iscriende o faeddende.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Su chi das a una IA: sa pregunta o sas istrutziones tuas, e cale si siat cosa chi li passas. Prompts prus craros de sòlitu portant rispostas mègius.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Ingegneria de sos prompts","text":"S'abilidade de iscriere prompts chi dant resultados afidabiles e ùtiles."},{"id":"sysprompt","g":"ai","word":"Prompt de sistema","text":"Istrutziones de fundu chi una IA retzit in antis chi sa cunversatzione cumintzet, chi fissant su rolu e sas règulas suas. Contant de prus de su chi iscries.","also":["prompts de sistema","istrutzione de sistema","istrutziones de sistema"]},{"id":"context","g":"ai","word":"Cuntestu","text":"Totu su chi sa IA podet bìdere mentras traballat: sas istrutziones, sos messàgios tuos, sos archìvios chi at lèghidu e sas rispostas de in antis.","noTip":1},{"id":"ctxwin","g":"ai","word":"Ventana de cuntestu","text":"Cantu una IA podet tènnere in mente a su matessi tempus, mesuradu in token. A pustis de cussu, sas partes prus betzas si perdent o benint resumidas.","also":["ventanas de cuntestu"]},{"id":"session","g":"ai","word":"Sessione","text":"Una cunversatzione de traballu cun una IA, dae su cumintzu a s'acabu. Una sessione noa cumintzat cun una memòria noa.","also":["sessiones"],"noTip":1},{"id":"memory","g":"ai","word":"Memòria","text":"Notas chi una IA tenet intre sas sessiones, gasi regordat sas preferèntzias tuas e sas detzisiones de in antis.","noTip":1},{"id":"hallucination","g":"ai","word":"Allutzinatzione","text":"Cando una IA narat cun totu sa seguresa calicuna cosa chi est inventada o isbagliada. Controlla sos fatos importantes.","also":["allutzinatziones","allutzinare","allutzinat"]},{"id":"training","g":"ai","word":"Allenamentu","text":"Allenare unu modellu mustrende·li cantidades mannas de esempros, in antis chi calicunu l'impreet.","also":["allenadu"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Datos de allenamentu","text":"Sos esempros dae sos cales unu modellu at imparadu. Sa connoschèntzia sua si firmat a sa data in ue cussos datos sunt istados collidos.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Lìmite de sa connoschèntzia","text":"Sa data in ue acabat sa connoschèntzia integrada de una IA. No at a connòschere sas cosas benidas a pustis, si no las chircat.","also":["knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Afinamentu","text":"Allenamentu in prus de unu modellu chi b'est giai, subra de sos esempros tuos, pro lu fàghere mègius in unu traballu particulare.","also":["afinare","afinadu","fine-tuning"]},{"id":"inference","g":"ai","word":"Inferèntzia","text":"Unu modellu IA impreadu a beru pro rispòndere a calicuna cosa, a diferèntzia de cando benit allenadu.","also":["inferèntzia de su modellu"]},{"id":"tooluse","g":"ai","word":"Impreu de ainas","text":"Una IA chi podet fàghere cosas, no isceti faeddare: esecutare cumandos, lèghere archìvios o chircare in sa rete, pro mèdiu de ainas chi s'app li dat.","also":["tool use","tool calling","tool call","tool calls","giamadas de ainas"]},{"id":"subagent","g":"ai","word":"Sub-agente","text":"Una IA agiudante a sa cale una IA printzipale dat unu traballu prus piticu, e dae sa cale retzit su resultadu.","also":["subagent","subagents","sub-agent","sub-agentes"]},{"id":"multiagent","g":"ai","word":"Multi-agente","text":"Prus IA chi traballant impare subra de unu traballu, cadauna cun sa parte sua, comente un'iscuadra pitica.","also":["sistema multi-agente"]},{"id":"autonomy","g":"ai","word":"Autonomia","text":"Cantu una IA podet fàghere a sa sola in antis chi depat pregontare a una persone.","also":["autonomous","autònomu"]},{"id":"hitl","g":"ai","word":"Persone in su circuitu","text":"Mantènnere una persone in mesu pro controllare o aprovare su chi faghet s'IA in sos puntos importantes. In AI-gile ses tue.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Barreras de protetzione","text":"Lìmites e controllos chi mantenent seguras sas atziones de una IA, comente su bisòngiu de un'aprovatzione in antis chi calicuna cosa andet in lìnea. Minimant s'arriscu de errores, ma no los eliminant de su totu.","also":["barrera de protetzione"]},{"id":"rag","g":"ai","word":"Generatzione aumentada dae sa chirca (RAG)","text":"Permìtere a una IA de chircare cosas in sos documentos tuos in antis de rispòndere, gasi sas rispostas suas si fundant in sos fatos tuos.","also":["RAG","generatzione aumentada dae sa chirca"]},{"id":"embedding","g":"ai","word":"Incorporatzione","text":"Trasformare unu testu in una lista de nùmeros chi nde pigat su sensu, gasi unu computer podet agatare cosas cun unu significadu simile.","also":["incorporatziones","embedding"]},{"id":"vectordb","g":"ai","word":"Base de datos vetoriale","text":"Una base de datos fata pro chircare in cussas listas de nùmeros (embedding), pro agatare materiale cun unu sensu simile.","also":["bases de datos vetoriales","depòsitu vetoriale"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Una manera comuna de collegare ainas e fontes de datos a sas app de IA, gasi una IA las podet impreare.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatura","text":"Un'impostatzione pro cantu sunt aventurosas sas rispostas de una IA. Bàscia dat rispostas prus firmas e prevedìbiles; arta nde dat de prus variadas. Nissuna de sas duas la faghet èssere semper giusta.","also":["temperatura de su modellu"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodale","text":"Capatze de traballare cun prus de una zenia de informatzione, comente testu, immàgines e sonu.","also":["multi-modale"]},{"id":"evals","g":"ai","word":"Valutatzione (eval)","text":"Una proa pianificada de cantu bene una IA faghet subra de esempros sèberados, gasi podes cumparare modellos o prompts.","also":["eval","evals","valutatziones"]},{"id":"bias","g":"ai","word":"Pregiudìtziu","text":"Cando una IA (o una persone) pendet in manera ingiusta a una parte, a s'ispissu pro more de su chi at imparadu.","also":["pregiudicadu"],"noTip":1},{"id":"responsible","g":"ai","word":"IA responsàbile","text":"Impreare sa IA in manera giusta, segura e onesta, cun sas persones galu responsàbiles de sos resultados.","also":["ethical AI","IA ètica"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"Unu trucu inue istrutziones cuadas in una pàgina web o in un'archìviu chircant de fàghere a una IA calicuna cosa chi s'utente suo no at dimandadu.","also":["prompt injections","injetzione de prompt"]},{"id":"ratelimit","g":"ai","word":"Lìmite de frecuèntzia","text":"Unu lìmite màssimu a cantas dimandas podes imbiare a unu servìtziu in unu tempus fissu. Si lu superas, depes isetare.","also":["rate limit","rate limits","rate limited","lìmites de frecuèntzia"]},{"id":"usagelimit","g":"ai","word":"Lìmite de impreu","text":"Cantu traballu IA su pianu tuo permitit in unu perìodu, a pustis de su cale si firmat o costat de prus.","also":["usage limits","lìmites de impreu"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Costruire software mescamente descriende a una IA ite boles e lassende·la iscriere su còdighe.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"Sa cantidade de dinare postu a banda pro calicuna cosa.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Istima de costu","text":"Unu càlculu a ogru de ite at a costare calicuna cosa in antis de cumintzare.","also":["istimas de costu"]},{"id":"roi","g":"money","word":"Ritornu subra de s'investimentu (ROI)","text":"Su chi torras a otènnere a cunfrontu de su chi as postu. Si est positivu, nd'at bàlidu sa pena.","also":["ROI"]},{"id":"tco","g":"money","word":"Costu totale de proprietade (TCO)","text":"Totu su chi calicuna cosa costat a beru in totu sa vida sua, no isceti su prètziu pro la comporare: funtzionamentu, assistèntzia, agiornamentos e a s'acabu su ritiru.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx e OpEx","text":"CapEx est dinare ispendidu in antis pro cosas chi mantenes; OpEx est ispesa chi sighit, comente sas faturas mensiles.","also":["CapEx","OpEx","ispesa in capitale","ispesa operativa"]},{"id":"subscription","g":"money","word":"Abbonamentu","text":"Pagare regularmente, de sòlitu a mese o a annu, pro sighire a impreare calicuna cosa.","also":["abbonamentos"],"noTip":1},{"id":"saas","g":"money","word":"Software comente servìtziu (SaaS)","text":"Software chi impreas in lìnea e pagas cun abbonamentu, mentras chie l'at fatu lu gestit pro tie.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pagare a su chi impreas","text":"Pagare isceti su chi impreas, comente su cloud o sos token IA.","also":["pay-as-you-go","usage-based pricing","prètziu a impreu"]},{"id":"overage","g":"money","word":"Ispesa in prus","text":"S'impreu in prus de su chi cumprendet su pianu tuo, chi podet costare de prus.","also":["overages","overage charges","ispesas in prus"]},{"id":"billingalert","g":"money","word":"Avisu de faturatzione","text":"Unu messàgiu cando s'ispesa o s'impreu arribat a unu livellu chi as sèberadu. Ti avisat, ma non semper firmat àteros costos.","also":["avisos de faturatzione","avisu de ispesa"]},{"id":"freetier","g":"money","word":"Livellu de badas","text":"Unu livellu de badas de unu servìtziu a pagamentu, cun lìmites. Ùtile pro cumintzare.","also":["pianu de badas"]},{"id":"pricing","g":"money","word":"Pianu de prètzios","text":"Sos pachetes diferentes chi unu servìtziu bendet, cadaunu cun su prètziu e sos lìmites suos.","also":["pricing plans","price plan","pianos de prètzios"]},{"id":"licence","g":"money","word":"Lissèntzia","text":"Sas règulas chi narant comente podes impreare, copiare, cambiare o cumpartzire calicuna cosa chi at fatu un'àteru, comente software, caràteres o immàgines.","also":["licences","license","licenses","lissèntzias"],"noTip":1},{"id":"opensource","g":"money","word":"Open source (fonte aberta)","text":"Software cun unu còdighe chi cale si siat persone podet lèghere, impreare e a s'ispissu cambiare de badas, sighende sas règulas de sa lissèntzia sua.","also":["open-source","open source software","OSS","fonte aberta","software a fonte aberta"]},{"id":"osslicence","g":"money","word":"Lissèntzia open source","text":"Sas règulas chi benint cun su còdighe open source. Unas cantas ti lassant fàghere belle totu (comente MIT); àteras ti pedint de cumpartzire fintzas sos càmbios tuos (comente GPL).","also":["open source licences","MIT licence","GPL","lissèntzias open source"]},{"id":"proprietary","g":"money","word":"Proprietàriu","text":"De proprietade de un'impresa e no lìberu de copiare o de cambiare. Su cuntràriu de s'open source.","also":["software proprietàriu"]},{"id":"copyright","g":"money","word":"Copyright","text":"Su deretu legale de chie creat calicuna cosa de controllare sas còpias de s'òpera sua, fintzas su còdighe e sos testos.","also":["cun copyright"],"noTip":1},{"id":"ip","g":"money","word":"Proprietade intelletuale (IP)","text":"Ideas e creatziones chi sa lege cunsiderat de proprietade de calicunu, comente còdighe, disinnos, nùmenes e logos.","also":["intellectual property","proprietade intelletuale"]},{"id":"tos","g":"money","word":"Cunditziones de servìtziu","text":"Sas règulas chi atzetas cando impreas unu servìtziu.","also":["tèrmines e cunditziones","cunditziones de impreu"]},{"id":"contract","g":"money","word":"Cuntratu","text":"Un'acordu iscritu intre duas partes chi sa lege sustenet.","also":["cuntratos"],"noTip":1},{"id":"sow","g":"money","word":"Descritzione de su traballu (SOW)","text":"Unu documentu chi fissat esatamente ite traballu s'at a fàghere, pro cando e pro cantu.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Prètziu fissu","text":"Unu prètziu cuncordadu pro totu su traballu, cale si siat su tempus chi bi cheret.","also":["fixed-price","a prètziu fissu"]},{"id":"tm","g":"money","word":"Tempus e materiales","text":"Pagare sas oras traballadas a beru e sas cosas impreadas a beru, imbetzes de unu prètziu fissu.","also":["T&M"]},{"id":"invoice","g":"money","word":"Fatura","text":"Unu cuntu chi pedit su pagamentu pro traballu fatu o benes frunidos.","also":["faturas"],"noTip":1},{"id":"lockin","g":"money","word":"Ligadura a su frunidore","text":"Cando lassare unu frunidore est tantu difìtzile o caru chi non ti nde podes prus istaccare.","also":["lock-in","vendor lock-in"]},{"id":"procurement","g":"money","word":"Acuistos","text":"Su protzessu de sèberare e comporare dae frunidores.","also":["procurement"]},{"id":"servicecredit","g":"money","word":"Crèditu de servìtziu","text":"Unu rimborsu o un'iscontu chi retzis cando unu frunidore no rispetat su SLA suo.","also":["service credits","crèditos de servìtziu"]}]}};
